import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {packRounds,socialPresentation} from './Social2230Rules';
import {socialSeed} from './Social1921Rules';
export const BALLOON_ID='balloon-bundle-festival',BALLOON=BALLOON_ID+'-balloon',TICKET=BALLOON_ID+'-wild',FESTIVAL_SCATTER=BALLOON_ID+'-scatter';
export const BALLOON_PAYS=[[1.5,4,8],[1.5,4,8],[1.2,2,4],[1,1.5,3],[.8,1.2,2],[.6,1,1.5],[.4,.6,1]];
export interface BalloonPlayback {free:boolean;counts:number[];tickets:number[];scatterSpins:number[];lineWins:Win[];pops:{cell:number;count:number;multiplier:number;freeSpins:number;win:Win}[];awarded:number;}
/** Own single-board adaptation. Bundles are individual prizes, never extra ways. */
export class BalloonBundleSlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly paylines:number[][]=[];readonly bets=[...BET_LEVELS];readonly maxWin=10000;readonly hasBonus=true;readonly usesLocalPayouts=true;readonly bonusCalibrationKey=BALLOON_ID+':bundle-v1';get bonusSymbol(){return FESTIVAL_SCATTER;}get bonusTriggerCount(){return 6;}
 readonly presentation=socialPresentation('풍선 묶음 순서대로 터뜨리기','풍선 묶음 축제');
 readonly config:SlotConfig={id:BALLOON_ID,title:'풍선 묶음 축제',subtitle:'BALLOON BUNDLE FESTIVAL',tag:'243 WAYS · BUNDLE POP',color:'#18294a',accent:'#f4ae70',description:'5×3 · 243 WAYS · 왼쪽부터 3개 릴 이상\n풍선은 칸마다 1~3개. 연결된 실제 풍선만 개당 베팅 1배 지급. 묶음 수는 WAYS를 늘리지 않습니다.\n금색 티켓은 ×2~5 와일드. 기본 3번 릴, 무료 중 2·3·4번 릴에 등장합니다.\n풍선 연결은 릴마다 가장 큰 티켓 배수를 곱해 적용. 5번 릴의 무료 표식도 같은 배수 적용.\n팔찌 6개 이상이면 팔찌당 1~3회 무료. 무료 중 풍선과 티켓 증가.\n무료 총100회 제한. 등장률·배당·티켓 결합은 자체 각색입니다.',symbols:['축제 트로피','붉은 실크 모자','롤러코스터 객차','보라 범퍼카','청색 회전목마','팝콘 통','나선 막대사탕','금색 티켓','풍선 묶음','축제 팔찌'].map((name,n)=>({id:BALLOON_ID+'-'+(n===7?'wild':n===8?'balloon':n===9?'scatter':n),name,color:'#f4ae70',weight:[5,6,7,9,11,14,17,3,8,4][n],payout:n<7?BALLOON_PAYS[n][2]:0}))};
 resolve(board:string[],bet:number,counts:number[],tickets:number[],scatterSpins:number[],free=false):SpinResult{
  if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!this.config.symbols.some(t=>t.id===s))||[counts,tickets,scatterSpins].some(a=>a.length!==15))throw Error('Invalid festival board');
  const lineWins:Win[]=[];
  for(let symbol=0;symbol<7;symbol++){
   const groups:number[][]=[];for(let c=0;c<5;c++){const cells=[c,c+5,c+10].filter(i=>board[i]===BALLOON_ID+'-'+symbol||board[i]===TICKET);if(!cells.length)break;groups.push(cells);}if(groups.length<3)continue;
   const ways=groups.reduce((n,g)=>n*g.reduce((sum,i)=>sum+(board[i]===TICKET?tickets[i]:1),0),1);
   lineWins.push({line:symbol,symbol:BALLOON_ID+'-'+symbol,cells:groups.flat(),multiplier:ways,amount:Math.round(bet*BALLOON_PAYS[symbol][groups.length-3]*ways)});
  }
  const groups:number[][]=[];for(let c=0;c<5;c++){const cells=[c,c+5,c+10].filter(i=>board[i]===BALLOON||board[i]===TICKET);if(!cells.length)break;groups.push(cells);}
  const pops:BalloonPlayback['pops']=[];let awarded=0;
  if(groups.length>=3){const multiple=groups.reduce((n,g)=>n*Math.max(1,...g.filter(i=>board[i]===TICKET).map(i=>tickets[i])),1);for(const cell of groups.flat().filter(i=>board[i]===BALLOON)){
   const extra=cell%5===4?scatterSpins[cell]*multiple:0;awarded+=extra;const win:Win={line:-1,symbol:BALLOON,cells:[cell],amount:bet*counts[cell]*multiple,multiplier:multiple};pops.push({cell,count:counts[cell],multiplier:multiple,freeSpins:extra,win});
  }}
  const scatters=board.flatMap((s,i)=>s===FESTIVAL_SCATTER?[i]:[]);if(scatters.length>=6)awarded+=scatters.reduce((n,i)=>n+scatterSpins[i],0);
  const wins=[...lineWins,...pops.map(p=>p.win)];return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),balloonFeature:{free,counts:[...counts],tickets:[...tickets],scatterSpins:[...scatterSpins],lineWins,pops,awarded},presentation:this.presentation};
 }
 evaluate(board:string[],bet:number){return this.resolve(board,bet,board.map(s=>s===BALLOON?1:0),board.map(s=>s===TICKET?2:0),board.map(s=>s===FESTIVAL_SCATTER?1:0));}
 private drawTables:{symbols:string[];limits:number[];total:number}[][]=[];
 private raw(rng:()=>number,free=false){
  if(!this.drawTables.length)this.drawTables=[false,true].map(free=>Array.from({length:5},(_,col)=>{const available=this.config.symbols.filter(s=>s.id!==TICKET||(free?[1,2,3]:[2]).includes(col));let total=0;const limits=available.map(s=>total+=s.weight*(free&&(s.id===BALLOON||s.id===TICKET)?1.35:1));return{symbols:available.map(s=>s.id),limits,total};}));
  const board:string[]=[],counts:number[]=[],tickets:number[]=[],scatterSpins:number[]=[];
  for(let i=0;i<15;i++){const t=this.drawTables[free?1:0][i%5],roll=rng()*t.total;let j=0;while(j<t.limits.length-1&&roll>=t.limits[j])j++;const symbol=t.symbols[j];board.push(symbol);counts.push(symbol===BALLOON?1+Math.floor(rng()*3):0);tickets.push(symbol===TICKET?2+Math.floor(rng()*4):0);scatterSpins.push(symbol===FESTIVAL_SCATTER?1+Math.floor(rng()*3):symbol===BALLOON&&i%5===4&&rng()<.18?1:0);}
  return{board,counts,tickets,scatterSpins};
 }
 private draw(bet:number,rng:()=>number,free=false){const d=this.raw(rng,free);return this.resolve(d.board,bet,d.counts,d.tickets,d.scatterSpins,free);}
 private sequence(base:SpinResult,rng:()=>number,purchase=false){const initial=Math.min(100,base.balloonFeature!.awarded);if(!initial)return base;const rounds:SpinResult[]=purchase?[]:[base];let remaining=initial,awarded=initial;while(remaining){remaining--;const r=this.draw(base.bet,rng,true),extra=Math.min(r.balloonFeature!.awarded,100-awarded);remaining+=extra;awarded+=extra;r.freeSpinsAdded=extra||undefined;r.freeSpinsRemaining=remaining;r.roundLabel='축제 무료 · 남은 '+remaining+'회';rounds.push(r);}let budget=base.bet*this.maxWin;for(const r of rounds){for(const w of r.wins){w.amount=Math.min(budget,w.amount);budget-=w.amount;}r.payout=r.wins.reduce((n,w)=>n+w.amount,0);}return packRounds(rounds,{freeSpinsAwarded:initial,featureName:'풍선 축제 무료 회전',presentation:this.presentation,bonusEndReason:budget===0?'max-win':'spins-exhausted',...(purchase?{bonusTriggerRound:{board:[...base.board],bet:base.bet,wins:[],payout:0,balloonFeature:{...base.balloonFeature!,lineWins:[],pops:base.balloonFeature!.pops.map(p=>({...p,win:{...p.win,amount:0}}))}}}:{})});}
 spin(bet:number,rng:()=>number=Math.random){return this.sequence(this.draw(bet,rng),rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');for(let i=0;i<200000;i++){const d=this.raw(rng),b=d.board;const scatter=b.filter(s=>s===FESTIVAL_SCATTER).length>=6;const marked=[4,9,14].some(i=>b[i]===BALLOON&&d.scatterSpins[i]>0)&&[0,1,2,3,4].every(c=>[c,c+5,c+10].some(i=>b[i]===BALLOON||b[i]===TICKET));if(scatter||marked)return this.sequence(this.resolve(b,bet,d.counts,d.tickets,d.scatterSpins),rng,true);}throw Error('Festival trigger unavailable');}
 demoSpin(bet:number){const rng=socialSeed(47928);for(let i=0;i<200000;i++){const r=this.spin(bet,rng);if(r.balloonFeature?.pops.length)return r;}throw Error('Festival demo unavailable');}
}
