import {ExpansionSlot,ExpansionFrame,Geometry,expansionCells as cells,randomIndex as ri} from './ExpansionCore';
import {SpinResult} from './SlotMain';
import {HEART_MODEL,HEART_INITIAL,HEART_LANDING,HEART_RANDOM_BOARD,heartOrdinary,heartQualifiedMask,heartUniform} from './HeartMath';
export class HeartLinkSlot extends ExpansionSlot {
 private drawingPhase:'base'|'natural'|'purchase'='base';
 unit(symbol:number,count:number){return (.025+.015*(8-symbol))*Math.pow(2,Math.max(0,count-3));}
 prize(board:string[],bet:number,multiple:number,focus:number[],caption:string,g:Geometry=this.geometry):ExpansionFrame{return this.frame(board,'win',caption,focus,{wins:[{line:-1,symbol:this.id('wild'),cells:[...focus],amount:Math.round(bet*multiple),multiplier:multiple}]},g);}
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const input=HEART_MODEL[this.drawingPhase],board=Array.from({length:g.columns*g.rows},()=>this.id(heartOrdinary(bet,rng,input)));
  for(let col=0;col<g.columns;col++)if(heartUniform(rng)<input.scatterPerReel)board[ri(rng,g.rows)*g.columns+col]=this.id('scatter');return board;
 }
 private freeRounds(base:SpinResult,bet:number,rng:()=>number,gates:number[],phase:'natural'|'purchase'){
  const previous=this.drawingPhase;this.drawingPhase=phase;try{return this.freeFromRound(base,bet,rng,6,b=>{const r=this.lineRound(b,bet);if(cells(b,this.id('scatter')).length>=3)r.freeSpinsAdded=6;return r;},gates);}finally{this.drawingPhase=previous;}
 }

 private lineRound(board:string[],bet:number){return this.round(bet,[this.frame(board,'reels','5×3 · 50라인 하트 금고'),this.hit(board,bet,'WILD 포함 라인 ×2',this.geometry,{wildMode:'double'})]);}
 private heartBoard(rng:()=>number){return Array.from({length:15},()=>this.id(heartUniform(rng)<HEART_INITIAL?'coin':7));}
 private linked(board:string[]){return Array.from({length:3},(_,row)=>Array.from({length:5},(_,col)=>row*5+col).filter(c=>board[c]===this.id('coin'))).sort((a,b)=>b.length-a.length)[0];}
 private holdRounds(bet:number,rng:()=>number,guaranteed:boolean){
  const mask=guaranteed?heartQualifiedMask(rng):undefined;let board=mask===undefined?this.heartBoard(rng):Array.from({length:15},(_,c)=>this.id(mask>>c&1?'coin':7)),anchors=this.linked(board);
  const held=new Set(cells(board,this.id('coin'))),award=anchors.length>=3?anchors.length:0;
  const panel=(remaining:number)=>({held:Array.from(held),values:board.map((_,c)=>held.has(c)?1:0),remaining});
  const entry=this.round(bet,[this.frame(board,'reels','별도 하트판 공개',[],{...panel(award),held:[]})]);
  if(!award)return [entry];
  entry.expansionFeature!.frames.push(this.frame(board,'trigger','같은 줄 하트 '+award+'개 · 리스핀 '+award+'회',anchors,panel(award)));
  const rounds=[entry];let remaining=award,played=0;
  while(remaining>0&&held.size<15&&played<60){
   const prior=Array.from(held),before=[...board];remaining--;played++;const landed:number[]=[];
   for(let cell=0;cell<15;cell++)if(!held.has(cell)&&heartUniform(rng)<HEART_LANDING){board[cell]=this.id('coin');landed.push(cell);}
   const reset=landed.some(c=>anchors.some(a=>Math.abs(c%5-a%5)+Math.abs(Math.floor(c/5)-Math.floor(a/5))===1));
   const fs=[this.frame(board,'reels','기존 하트 유지 · 빈칸 리스핀',[],{held:prior,remaining,values:board.map(id=>id===this.id('coin')?1:0)})];
   landed.forEach(c=>held.add(c));if(reset)remaining=award;
   if(landed.length)fs.push(this.frame(board,'trigger','새 하트 착지',landed,{...panel(remaining),held:prior}));
   fs.push(this.frame(board,'reveal',reset?'시작 하트 옆 착지 · '+award+'회 복구':'남은 리스핀 '+remaining,landed,panel(remaining)));
   rounds.push(this.round(bet,fs,{heldAtStart:prior.map(cell=>({cell,symbol:this.id('coin'),value:1}))}));
  }
  const doubled=held.size===15,fs=[this.frame(board,'state',doubled?'15칸 완성 · 모든 하트 ×2':'하트 상금 최종 확정',[],{...panel(0),values:board.map((_,c)=>held.has(c)?doubled?2:1:0)})];
  for(const cell of held)fs.push({...this.prize(board,bet,doubled?2:1,[cell],'고정 하트 한 번 지급'),...panel(0),values:board.map((_,c)=>held.has(c)?doubled?2:1:0)});
  rounds.push(this.round(bet,fs));return rounds;
 }
 play(board:string[],bet:number,rng:()=>number){
  const base=this.lineRound(board,bet),gates=cells(board,this.id('scatter'));
  if(gates.length>=3){
   base.expansionFeature!.frames.push(this.prize(board,bet,5,gates,'금고 표식 3개 · 별도 상금'));
   base.wins=base.expansionFeature!.frames.flatMap(f=>f.wins);base.payout=base.wins.reduce((n,w)=>n+w.amount,0);
   const clone=()=>JSON.parse(JSON.stringify(base)) as SpinResult;
   const free=this.freeRounds(clone(),bet,rng,gates,'natural');
   const holdBase=clone();holdBase.expansionFeature!.frames.push(this.frame(board,'trigger','하트 연결 금고 선택',gates));
   const hold=this.finish([holdBase,...this.holdRounds(bet,rng,true)],{featureOnly:true,featureName:'하트 연결 금고'});
   return this.choices('금고 보너스를 선택하세요',['무료 6회','하트 연결 리스핀'],[free,hold]);
  }
  if(heartUniform(rng)<HEART_RANDOM_BOARD){base.expansionFeature!.frames.push(this.frame(board,'trigger','금고 열림 · 별도 하트판 1회'));return this.finish([base,...this.holdRounds(bet,rng,false)],{featureOnly:true,featureName:'하트판 공개'});}
  return this.finish([base]);
 }
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  // A heart hold pays at most30 bets, so cannot be a98% purchase at100 bets.
  // Retain both natural choices; purchase the genuine six-free-round branch.
  const reels=[0,1,2,3,4];for(let i=4;i>0;i--){const j=ri(rng,i+1);[reels[i],reels[j]]=[reels[j],reels[i]];}
  const board=Array.from({length:15},()=>this.id(heartOrdinary(bet,rng,HEART_MODEL.base))),gates=reels.slice(0,3).map(col=>ri(rng,3)*5+col);gates.forEach(c=>board[c]=this.id('scatter'));
  const base=this.round(bet,[this.frame(board,'trigger','5×3 · 50라인 하트 금고',gates)]);return this.purchaseFromResult(this.freeRounds(base,bet,rng,gates,'purchase'));
 }
}
