import {ExpansionSlot,Geometry,expansionCells as cells,randomIndex} from './ExpansionCore';
import {RIDGE_MODEL,ridgeUniform,ridgeOrdinary} from './WolfStackMath';
/** Local 40-line adaptation of the documented stacked-wild / five-free-spin rules. */
export class WolfStackSlot extends ExpansionSlot {
 private drawingFree=false;
 unit(symbol:number,count:number){return(.025+.015*(8-symbol))*2**Math.max(0,count-3);}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-moon';}
 private stacks(board:string[],rng:()=>number){
  for(let col=0;col<5;col++){const occupied=[col,col+5,col+10],wilds=occupied.filter(c=>board[c]===this.id('wild'));if(!wilds.length)continue;
   const anchor=Math.floor(wilds[0]/5),size=2+randomIndex(rng,2),starts=Array.from({length:4-size},(_,i)=>i).filter(start=>start<=anchor&&anchor<start+size),start=starts[randomIndex(rng,starts.length)];
   for(let row=start;row<start+size;row++){const c=row*5+col;if(board[c]!==this.id('scatter'))board[c]=this.id('wild');}
  }return board;
 }
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){
  if(!this.bets.includes(bet)||g.columns!==5||g.rows!==3)throw Error('Invalid ridge wager or geometry');const high=this.drawingFree?RIDGE_MODEL.freeHighByBet[bet]:RIDGE_MODEL.baseHighByBet[bet],moon=this.drawingFree?RIDGE_MODEL.freeMoon:RIDGE_MODEL.baseMoon,board=Array.from({length:15},()=>this.id(ridgeOrdinary(high,rng)));
  for(const col of [1,2,3])if(ridgeUniform(rng)<moon)board[Math.floor(ridgeUniform(rng)*3)*5+col]=this.id('scatter');
  return this.stacks(board,rng);
 }
 private gates(board:string[]){const found=cells(board,this.id('scatter')).filter(c=>c%5>0&&c%5<4);return new Set(found.map(c=>c%5)).size===3?found:[];}
 private roundWithStacks(board:string[],bet:number){const wilds=cells(board,this.id('wild')),frames=[this.frame(board,'reels','늑대 스택 착지')];if(wilds.length)frames.push(this.frame(board,'trigger','세로 늑대 스택 · WILD 대체',wilds));frames.push(this.hit(board,bet,'40라인 · 늑대 스택 당첨'));const gates=this.gates(board);if(gates.length){const prize=this.prize(board,bet,2,gates,'가운데 세 달 · 베팅 2배');prize.wins.forEach(w=>{w.amount=bet*2;w.multiplier=2;w.symbol=this.id('scatter');});frames.push(prize);}return this.round(bet,frames);}
 play(board:string[],bet:number,rng:()=>number){const base=this.roundWithStacks(board,bet),gates=this.gates(board);if(!gates.length)return this.finish([base]);const saved=this.drawingFree;this.drawingFree=true;try{return this.freeFromRound(base,bet,rng,5,b=>{const round=this.roundWithStacks(b,bet);if(this.gates(b).length)round.freeSpinsAdded=5;return round;},gates);}finally{this.drawingFree=saved;}}
 prepareBonusPurchase(bet:number,rng:()=>number){
  // The independent center flags are conditioned on all three moons. Their
  // declared uniform rows and unchanged protected-WILD stacks remain native.
  if(!this.bets.includes(bet))throw Error('Invalid bet');const board=Array.from({length:15},()=>this.id(ridgeOrdinary(RIDGE_MODEL.baseHighByBet[bet],rng)));
  for(const col of [1,2,3])board[Math.floor(ridgeUniform(rng)*3)*5+col]=this.id('scatter');
  const result=this.purchaseFromResult(this.play(this.stacks(board,rng),bet,rng)),trigger=result.bonusTriggerRound!;
  trigger.expansionFeature!.frames=[this.frame(trigger.board,'trigger','독립 무료 5회',this.gates(trigger.board))];return result;
 }
}
