export function cannonUniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Cannon uniform');return u;}
export function cannonOrdinary(high:number,rng:()=>number){const w=[5*high,6,7,8,10,12,14,16,2];let x=cannonUniform(rng)*w.reduce((a,b)=>a+b,0);for(let k=0;k<w.length;k++){x-=w[k];if(x<0)return k===8?'wild':String(k);}return 'wild';}
