import {bindButtonFeedback,buttonFace} from './ButtonFeedback';
import {features} from '../services/FeatureFlags';
import {i18n,tr} from '../services/Localization';
import {formatAmount} from '../services/AmountFormat';
import {Node,Graphics,Color,UITransform,Label,Font,Vec3,tween,Tween,Sprite,SpriteFrame} from 'cc';
import {uiIcon} from './UIIcons';
import {addModalBackdrop} from './ModalBackdrop';
export interface BonusPopupTheme {name:string;accent:string;background:string;secondary:string;titleFrame?:SpriteFrame;symbolFrame?:SpriteFrame;}
function darken(hex:string){const c=new Color(hex);return new Color(Math.round(c.r*.24),Math.round(c.g*.24),Math.round(c.b*.24),255);}
/** Slot artwork and colours on a centered card; the game remains visible outside it. */
export class FreeSpinPopup {
 readonly root:Node;
 private amountCounter={value:0};
 constructor(parent:Node,width:number,height:number,contentWidth:number,font:Font|null,mode:'entry'|'exit',count:number,payout:number,title:string,onContinue:()=>void,tickets=0,presentation?:{title?:string;amount?:string;detail?:string},theme?:BonusPopupTheme){
  const root=this.root=new Node('Free spins '+mode);root.layer=parent.layer;parent.addChild(root);
  addModalBackdrop(root,width,height,'Free spins backdrop');
  const card=new Node('Slot bonus card');card.layer=root.layer;root.addChild(card);
  const w=Math.min(contentWidth-64,560),h=Math.min(height*.5,428),accent=theme?.accent||'#ffd16f',secondary=theme?.secondary||'#86ead0';
  const node=(name:string,x:number,y:number,nw:number,nh:number)=>{const n=new Node(name);n.layer=root.layer;card.addChild(n);n.setPosition(x,y);n.addComponent(UITransform).setContentSize(nw,nh);return n;};
  const rect=(name:string,x:number,y:number,nw:number,nh:number,color:string|Color)=>{const n=node(name,x,y,nw,nh),g=n.addComponent(Graphics);g.fillColor=typeof color==='string'?new Color(color):color;g.roundRect(-nw/2,-nh/2,nw,nh,Math.min(14,nh/3));g.fill();return n;};
  const text=(name:string,value:string,x:number,y:number,nw:number,nh:number,size:number,color:string)=>{const n=node(name,x,y,nw,nh),l=n.addComponent(Label);l.fontFamily=i18n.fontFamily;l.string=tr(value);l.fontSize=size;l.lineHeight=size*1.18;l.isBold=true;l.color=new Color(color);l.horizontalAlign=Label.HorizontalAlign.CENTER;l.verticalAlign=Label.VerticalAlign.CENTER;l.overflow=Label.Overflow.SHRINK;l.enableWrapText=false;n.getComponent(UITransform)!.setContentSize(nw,nh);return n;};
  const art=(name:string,frame:SpriteFrame,x:number,y:number,maxW:number,maxH:number)=>{const scale=Math.min(maxW/frame.rect.width,maxH/frame.rect.height),n=node(name,x,y,maxW,maxH),sp=n.addComponent(Sprite);sp.sizeMode=Sprite.SizeMode.CUSTOM;sp.spriteFrame=frame;n.getComponent(UITransform)!.setContentSize(frame.rect.width*scale,frame.rect.height*scale);return n;};
  rect('Card shadow',5,-7,w+4,h+4,'#0b101c');rect('Slot accent frame',0,0,w,h,accent);rect('Slot themed panel',0,0,w-6,h-6,darken(theme?.background||'#64538d'));
  rect('Inner border',0,0,w-20,h-20,'#222d40');rect('Inner panel',0,0,w-24,h-24,darken(theme?.background||'#64538d'));
  if(theme?.titleFrame)art('Bonus slot title',theme.titleFrame,0,h/2-66,w-72,88);
  else text('Bonus slot name',theme?.name||title,0,h/2-64,w-64,78,28,'#fff1d0');
  rect('Bonus stage bar',0,h/2-132,w-60,38,'#25334b');
  text('Bonus stage',presentation?.title||(mode==='entry'?title:'축하합니다!'),0,h/2-132,w-78,34,24,accent);
  if(theme?.symbolFrame){for(const side of [-1,1])art('Slot feature emblem',theme.symbolFrame,side*(w/2-60),-14,64,70);}
  else uiIcon(node('Bonus emblem',-w/2+62,-14,48,48).addComponent(Graphics),mode==='entry'?'star':'coin',48);
  const amount=mode==='entry'?(presentation?.amount||count+'회'):(presentation?.amount||formatAmount(payout));
  const amountNode=text('Bonus amount',amount,0,-10,w-166,72,mode==='entry'?48:52,'#fff1be');
  if(mode==='exit'&&!presentation?.amount&&payout>0){
   const label=amountNode.getComponent(Label)!;label.string=formatAmount(0);
   tween(this.amountCounter).to(.48,{value:payout},{easing:'cubicOut',onUpdate:()=>{label.string=formatAmount(Math.round(this.amountCounter.value));}}).call(()=>{label.string=formatAmount(payout);}).start();
  }
  if(mode==='exit')text('Bonus currency',features.tickets&&tickets?'COINS  +  '+formatAmount(Number((tickets/10).toFixed(1)))+'T':'COINS',0,-55,w-100,26,16,secondary);
  const detail=text('Bonus detail',presentation?.detail||(mode==='entry'?i18n.t('ui.bonus.entry.defaultDetail'):count+'회 · 보너스 획득 완료'),0,-h/2+105,w-64,44,18,'#dce5f2');detail.getComponent(Label)!.isBold=false;detail.getComponent(Label)!.enableWrapText=true;
  const button=rect('Continue free spins',0,-h/2+46,w-64,60,accent);text('Continue label',mode==='entry'?'시작':'확인',0,-h/2+46,w-90,44,23,'#172334').setParent(button,true);buttonFace(button,accent,'#fff0bd',true);bindButtonFeedback(button,onContinue);
  for(const side of [-1,1])for(const sy of [-1,1]){const mark=rect('Theme corner jewel',side*(w/2-19),sy*(h/2-23),7,18,secondary);mark.angle=45;}
  for(const side of [-1,1])for(let i=0;i<3;i++){const spark=node('Bonus edge sparkle',side*(w/2-28),32-i*30,9,9);uiIcon(spark.addComponent(Graphics),'star',9,accent);tween(spark).delay(i*.12).to(.5,{scale:new Vec3(1.2,1.2,1)}).to(.5,{scale:new Vec3(.7,.7,1)}).union().repeatForever().start();}
  card.setScale(.94,.94,1);tween(card).to(.22,{scale:new Vec3(1,1,1)},{easing:'backOut'}).start();
 }
 close(){Tween.stopAllByTarget(this.amountCounter);this.root.removeFromParent();this.root.destroy();}
}
