import {LocalStorage} from './AccountStorage';
import {WEEKLY_FREE_SPIN_COUNT,WEEKLY_FREE_SPIN_REWARD,WeeklyFreeSpinState} from './WeeklyFreeSpins';

export interface LocalFreeSpinLease {id:string;weekKey:string;day:number;slot:string;basePlayed:number;spinCount?:number;}
interface Journal {lease:LocalFreeSpinLease;baseCoins:number;baseReward:boolean;save:string;closing?:'completed'|'forfeited';}
/** The campaign's per-spin writes stay on this device. Only its final aggregate
 * is sent to the server; the normal cloud wallet is never overwritten by this save. */
export class LocalFreeSpinSession implements LocalStorage {
 private constructor(private storage:LocalStorage,private key:string,private journal:Journal){}
 static load(storage:LocalStorage,uid:string){
  const key='pocket-local-free-spins:'+uid,raw=storage.getItem(key);if(!raw)return null;
  const journal=JSON.parse(raw) as Journal;
  if(!journal?.lease?.id||typeof journal.save!=='string'||!Number.isSafeInteger(journal.baseCoins))throw Error('기기에 저장된 프리스핀 기록을 확인하지 못했습니다.');
  return new LocalFreeSpinSession(storage,key,journal);
 }
 static open(storage:LocalStorage,uid:string,lease:LocalFreeSpinLease,save:unknown){
  const initial=save as {coins:number;weeklyFreeSpins:WeeklyFreeSpinState};
  const old=this.load(storage,uid);if(old){
   if(old.lease.id!==lease.id)throw Error('이전 프리스핀 정산을 먼저 완료해 주세요.');
   if(!old.closing){const local=JSON.parse(old.journal.save),coins=initial.coins+local.coins-old.journal.baseCoins;
    if(!Number.isSafeInteger(coins)||coins<0)throw Error('프리스핀 잔액을 확인하지 못했습니다.');
    old.persist({...old.journal,baseCoins:initial.coins,save:JSON.stringify({...initial,coins,weeklyFreeSpins:local.weeklyFreeSpins})});
   }return old;
  }
  const session=new LocalFreeSpinSession(storage,'pocket-local-free-spins:'+uid,{lease,baseCoins:initial.coins,baseReward:initial.weeklyFreeSpins.rewardGranted,save:JSON.stringify(save)});
  session.persist(session.journal);return session;
 }
 get lease(){return this.journal.lease;}
 get state():WeeklyFreeSpinState{return JSON.parse(this.journal.save).weeklyFreeSpins;}
 get closing(){return this.journal.closing;}
 getItem(){return this.journal.save;}
 setItem(_key:string,value:string){if(this.closing)throw Error('프리스핀 완료 상태를 저장 중입니다.');this.persist({...this.journal,save:value});}
 private persist(next:Journal){this.storage.setItem(this.key,JSON.stringify(next));this.journal=next;}
 finish(outcome:'completed'|'forfeited'){
  if(this.closing&&this.closing!==outcome)throw Error('프리스핀 종료 요청이 이미 저장되어 있습니다.');
  const save=JSON.parse(this.journal.save),played=save.weeklyFreeSpins.days[this.lease.day].played;
  if(outcome==='completed'&&(this.lease.spinCount===undefined?played<WEEKLY_FREE_SPIN_COUNT:played!==this.lease.spinCount))throw Error('프리스핀을 모두 진행해 주세요.');
  const payout=save.coins-this.journal.baseCoins-(!this.journal.baseReward&&save.weeklyFreeSpins.rewardGranted?WEEKLY_FREE_SPIN_REWARD:0);
  if(!Number.isSafeInteger(payout)||payout<0)throw Error('프리스핀 당첨 합계를 확인하지 못했습니다.');
  this.persist({...this.journal,closing:outcome});
  return {sessionId:this.lease.id,played,payout,outcome};
 }
 clear(){this.storage.setItem(this.key,'');}
}
