import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {RoadCar,ROAD_MODES,RoadMode} from './RoadRules';
import {ROAD_ART,ROAD_EFFECT_ART,RoadHold,roadPlayback,roadSymbol as symbol} from './RoadFeature';

/** Dedicated delivered-art driving preview. Ordinary connected ways, yellow
 * growth, mystery, preparation route and queued upgrades remain draft backlog. */
export class RoadPreviewSlot extends SlotMain {
 readonly columns=5;readonly rows:number;readonly mode='lines' as const;readonly paylines:number[][]=[];
 readonly bets=[...BET_LEVELS];
 constructor(private readonly fixture='collision'){super();this.rows=fixture==='city'?5:fixture==='highway'?4:3;}
 get bonusSymbol(){return symbol('traffic_light');}
 readonly config:SlotConfig={id:'road-rage-x',title:'출근 대소동',subtitle:'COMMUTE CHAOS',tag:'1차 주행 체험',color:'#354151',accent:'#f3c96d',description:'빨강은 왼쪽 · 초록은 오른쪽\n통과한 심볼의 배수 증가\n마주 오는 차량 충돌 시 배수 합산\n보너스 고정 차량은 다음 회전에도 유지',symbols:ROAD_ART.map(art=>({id:symbol(art),name:art==='traffic_light'?'신호등':art==='collision_wild'?'WILD':art.replace(/_/g,' '),color:'#f3c96d',weight:0,payout:0}))};
 artResource(id:string){const name=id.slice('road-rage-x-'.length);if(![...ROAD_ART,...ROAD_EFFECT_ART].includes(name))throw Error('Unknown Road art');return 'slot-art-delivered-v1/road-rage-x/v05/'+name;}
 spin():SpinResult{throw Error('Road first draft is free playback only');}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const blank=()=>Array.from({length:this.rows*5},(_,i)=>symbol(ROAD_ART[(i+i%5)%10]));
  if(this.fixture==='no-win')return roadPlayback(this.rows,blank(),[],[],Array(this.rows*5).fill(1),[],bet);
  const bonus=['morning','highway','city','sticky'].includes(this.fixture);
  if(!bonus){const board=blank(),cars:RoadCar[]=this.fixture==='drive'?[{cell:4,color:'red',multiplier:2,sticky:false},{cell:10,color:'green',multiplier:3,sticky:false}]:[{cell:5,color:'green',multiplier:2,sticky:false},{cell:9,color:'red',multiplier:3,sticky:false}];cars.forEach(car=>board[car.cell]=symbol(car.color+'_car'));
   if(this.fixture==='blocked')board[7]=symbol('traffic_light');
   const awards:Win[]=this.fixture==='blocked'?[]:[{line:-1,symbol:symbol('collision_wild'),amount:bet*5,cells:this.fixture==='drive'?[0,14]:[5,7,9]}];
   return roadPlayback(this.rows,board,cars,[],Array(board.length).fill(1),awards,bet);
  }
  const mode:RoadMode=this.fixture==='highway'?'highway':this.fixture==='city'?'city':'morning',count=ROAD_MODES[mode].spins;
  const trigger=blank();for(let i=0;i<this.rows;i++)trigger[i*5+i]=this.bonusSymbol;
  const rounds:SpinResult[]=[{bet,board:trigger,payout:0,wins:[]}];let held:RoadHold[]=[];
  for(let index=0;index<count;index++){
   const board=blank(),values=Array(board.length).fill(1),cars:RoadCar[]=index===0?[{cell:5,color:'green',multiplier:2,sticky:true},{cell:9,color:'red',multiplier:3,sticky:false}]:index===1?[{cell:0,color:'green',multiplier:2,sticky:false}]:[];
   held.forEach(hold=>{board[hold.cell]=hold.symbol;values[hold.cell]=hold.value;});cars.forEach(car=>board[car.cell]=symbol(car.color+'_car'));
   const round=roadPlayback(this.rows,board,cars,held,values,index<2?[{line:-1,symbol:symbol('collision_wild'),amount:bet*(index?2:5),cells:index?[0,4]:[5,7,9]}]:[],bet);
   held=round.roadFeature!.heldAfter;round.freeSpinsRemaining=count-index-1;round.roundLabel=`주행 보너스 · ${index+1}회 · 남은 ${count-index-1}회`;rounds.push(round);
  }
  return {bet,board:[...rounds[rounds.length-1].board],wins:rounds.flatMap(round=>round.wins),payout:rounds.reduce((sum,round)=>sum+round.payout,0),rounds,freeSpinsAwarded:count,featureName:'출근 대소동 · 주행 보너스',bonusEndReason:'spins-exhausted'};
 }
}
