import{THUNDER_MODEL}from'./ThunderKeptMath';
import{thunderInputBoard}from'./ThunderInputBoard';
import {ExpansionSlot,Geometry,ExpansionFrame,expansionCells as cells,randomIndex} from './ExpansionCore';
/** Fifty local lines, two fixed held respins and a separate ten-free-game bonus. */
export class ThunderKeptSlot extends ExpansionSlot {
 readonly rules=['ui.thunder.guide.paths','ui.thunder.guide.held','ui.thunder.guide.free','ui.thunder.guide.buy'];
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-olympus';}
 private grid(bet:number,rng:()=>number,free:boolean,conditional=false){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const M=THUNDER_MODEL;
  return thunderInputBoard(this.config.id,(free?M.freeZeroByBet:M.baseZeroByBet)[bet],free?M.freeWild:M.baseWild,free?M.freeGate:M.gate,rng,free,conditional);
 }
 draw(bet:number,rng:()=>number,_g:Geometry=this.geometry){return this.grid(bet,rng,false);}
 private held(board:string[]){return board.flatMap((id,c)=>id===this.id(0)||id===this.id('wild')?[c]:[]);}
 private gate(board:string[]){const gates=cells(board,this.id('scatter')).filter(c=>c%5<3);return new Set(gates.map(c=>c%5)).size===3?gates:[];}
 private stormRound(input:string[],bet:number,rng:()=>number,free:boolean){let board=[...input];const frames:ExpansionFrame[]=[this.frame(board,'reels',free?'무료 10 · 천둥왕과 WILD 증가':'올림포스 릴 착지'),this.hit(board,bet,'50라인 당첨')];const triggered=[0,5,10,15].every(c=>board[c]===this.id(0));if(triggered){let held=this.held(board);frames.push(this.frame(board,'trigger','첫 릴 천둥왕 완성 · 고정 리스핀 2회',[0,5,10,15],{held,remaining:2}));for(let left=2;left>0&&held.length<20;left--){const before=[...held],next=this.grid(bet,rng,free);before.forEach(c=>next[c]=board[c]);board=next;frames.push(this.frame(board,'reels','천둥왕·WILD 보존 · 리스핀 '+left,[],{held:before,remaining:left-1}));held=this.held(board);const added=held.filter(c=>!before.includes(c));if(added.length)frames.push(this.frame(board,'effect','새 천둥왕·WILD 고정',added,{held,remaining:left-1}));const hit=this.hit(board,bet,held.length===20?'20칸 완성 · 즉시 최종 당첨':'고정 리스핀 당첨');hit.held=[...held];hit.remaining=left-1;frames.push(hit);}frames.push(this.frame(board,'state','고정 리스핀 완료',held,{held,remaining:0}));}return this.round(bet,frames);}
 play(board:string[],bet:number,rng:()=>number){const base=this.stormRound(board,bet,rng,false),gate=this.gate(board);if(!gate.length)return this.finish([base]);base.expansionFeature!.frames.push(this.frame(base.board,'trigger','첫 세 릴 번개 · 무료 10회',gate));const rounds=[base];let left=10,total=10;while(left>0){left--;const b=this.grid(bet,rng,true),round=this.stormRound(b,bet,rng,true),added=this.gate(b).length?Math.min(10,200-total):0;if(added){left+=added;total+=added;round.freeSpinsAdded=added;round.expansionFeature!.frames.push(this.frame(round.board,'trigger','무료 +10회',this.gate(b)));}round.freeSpinsRemaining=left;rounds.push(round);}return this.finish(rounds,{freeSpinsAwarded:10,featureOnly:false});}
 prepareBonusPurchase(bet:number,rng:()=>number){return this.purchaseFromResult(this.play(this.grid(bet,rng,false,true),bet,rng));}
}
