export const CITY_PRIZES=[1,2,5,15,50],CITY_PRIZE_WEIGHTS=[.6,.25,.11,.035,.005],CITY_ORDINARY_WEIGHTS=[5,6,7,8,10,12,14,16,2];
const pools=new Map<CityProfile,Map<number,{high:number;weights:number[];sum:number}>>();
export function cityUniform(rng:()=>number){const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid City random value');return value;}
export function cityCellInput(bet:number,rng:()=>number,profile:CityProfile){
 const u=cityUniform(rng);if(u>=1-profile.coin)return 'coin';const high=profile.highByBet[bet]??1;let byBet=pools.get(profile);if(!byBet){byBet=new Map();pools.set(profile,byBet);}let pool=byBet.get(bet);
 if(!pool||pool.high!==high){const weights=CITY_ORDINARY_WEIGHTS.map((w,i)=>w*(i===0?high:1));pool={high,weights,sum:weights.reduce((n,w)=>n+w,0)};byBet.set(bet,pool);}
 let sample=u/(1-profile.coin)*pool.sum;for(let i=0;i<9;i++){sample-=pool.weights[i];if(sample<0)return i===8?'wild':i;}return 7;
}
export function cityPrize(rng:()=>number){let sample=cityUniform(rng)*(.995+.005*CITY_MODEL.prizeHigh);for(let i=0;i<5;i++){sample-=CITY_PRIZE_WEIGHTS[i]*(i===4?CITY_MODEL.prizeHigh:1);if(sample<0)return CITY_PRIZES[i];}return 50;}
