import {BET_LEVELS} from './BetLevels';
import {NEON_MODEL,neonUniform,neonOrdinary} from './NeonBandMath';
import {SlotMain,SlotConfig,SpinResult,Win,SlotPresentation} from './SlotMain';
import {WOLF_LINES} from './WolfRules';
import {social1921Pays,validateSocialBoard,lineAwards,totalAwards,socialSeed} from './Social1921Rules';
export const BAND_ID='neon-band-mixer';
export interface BandPlayback {multipliers:number[];free:boolean;awards:Win[];}
/** Historical source confirms line-owned multipliers and a free-spin boost.
 * 25 lines, resampling each spin, ×2 free boost and 8 spins are local rules. */
export class NeonBandSlot extends SlotMain {
 readonly usesLocalPayouts=true;readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];readonly hasBonus=true;readonly maxWin=10000;
 readonly bonusCalibrationKey=BAND_ID+':line-mix-v1';get bonusSymbol(){return BAND_ID+'-scatter';}
 readonly presentation:SlotPresentation={evidence:'source-title-pending',anticipationText:'공연 티켓을 모읍니다',triggerText:'네온 무대 개막',bonusInText:'8회 · 모든 라인 배수 두 배',hitText:'라인별 믹서 지급',totalWinText:'공연 총 보상',signature:'라인마다 자기 배수',uiEffect:'당첨선 채널별 배수 점등',soundCue:'featureLand',anticipationHold:.3,hitHold:.25,outHold:.4};
 readonly config:SlotConfig={id:BAND_ID,title:'네온 밴드 믹서',subtitle:'NEON BAND MIXER',tag:'LINE MULTIPLIERS',color:'#343049',accent:'#d698e6',description:'5×3 · 25라인 · 왼쪽부터 3개 이상\n각 회전에서 라인마다 ×1/2/3/5 배수를 새로 정합니다.\n티켓 3개 이상: 무료 8회, 라인 배수 두 배\n무료 중 티켓 3개 이상: +4회\n배수는 해당 라인에만 적용, 다음 회전에 초기화됩니다.\n무료 회전은 최대1000회까지 진행합니다.',symbols:['기타','마이크','신시사이저','드럼','헤드폰','앰프','레코드','무대등','믹서 WILD','공연 티켓'].map((name,n)=>({id:BAND_ID+'-'+(n===8?'wild':n===9?'scatter':n),name,color:'#d698e6',weight:[5,6,7,8,10,12,14,16,2,3][n],payout:n<8?social1921Pays(BAND_ID)[n][2]:0}))};
 evaluate(board:string[],bet:number,multipliers:number[]=Array(25).fill(1),free=false):SpinResult{
  validateSocialBoard(this.config,board,bet,this.bets,15);if(multipliers.length!==25||multipliers.some(n=>!Number.isInteger(n)||n<1||n>10))throw Error('Invalid line multiplier');
  const wins=lineAwards(BAND_ID,board,bet,multipliers);return totalAwards({board:[...board],bet,wins,payout:0,bandFeature:{multipliers:[...multipliers],free,awards:wins},presentation:this.presentation});
 }
 private grid(bet:number,rng:()=>number,free:boolean,conditional=false){if(!this.bets.includes(bet))throw Error('Invalid Neon bet');const high=free?NEON_MODEL.freeHighByBet[bet]:NEON_MODEL.highByBet[bet],q=free?NEON_MODEL.freeGate:NEON_MODEL.gate,board=Array.from({length:15},()=>BAND_ID+'-'+neonOrdinary(high,rng));let flags=0;
  if(conditional){const options:Array<{mask:number;mass:number}>=[];let total=0;for(let mask=0;mask<32;mask++){const n=mask.toString(2).replace(/0/g,'').length;if(n<3)continue;const mass=q**n*(1-q)**(5-n);options.push({mask,mass});total+=mass;}let pick=neonUniform(rng)*total;flags=options[options.length-1].mask;for(const o of options){pick-=o.mass;if(pick<0){flags=o.mask;break;}}}else for(let col=0;col<5;col++)if(neonUniform(rng)<q)flags|=1<<col;
  for(let col=0;col<5;col++)if(flags&(1<<col))board[Math.floor(neonUniform(rng)*3)*5+col]=this.bonusSymbol;return board;
 }
 private round(bet:number,rng:()=>number,free:boolean){const mult=Array.from({length:25},()=>{const r=neonUniform(rng);return(r<.8?1:r<.95?2:r<.99?3:5)*(free?2:1);});return this.evaluate(this.grid(bet,rng,free),bet,mult,free);}
 private sequence(base:SpinResult,rng:()=>number){let awarded=0;const result=this.freeSpinSequence(base,()=>this.round(base.bet,rng,true),r=>{if(r.board.filter(id=>id===this.bonusSymbol).length<3)return 0;const added=Math.min(r===base?8:4,1000-awarded);awarded+=added;return added;});if(result.rounds){result.presentation=this.presentation;result.featureName='네온 앙코르 · 라인 배수 두 배';result.bonusEndReason=result.payout>=base.bet*this.maxWin?'max-win':'spins-exhausted';}return result;}
 spin(bet:number,rng:()=>number=Math.random){return this.sequence(this.round(bet,rng,false),rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){const board=this.grid(bet,rng,false,true),base:SpinResult={board,bet,wins:[],payout:0,presentation:this.presentation};const result=this.sequence(base,rng);result.bonusTriggerRound=base;result.rounds=result.rounds!.slice(1);result.wins=result.rounds.flatMap(r=>r.wins);return totalAwards(result);}
 demoSpin(bet:number){const board=Array.from({length:15},(_,i)=>BAND_ID+'-'+i%8);for(const c of [5,6,7])board[c]=BAND_ID+'-0';const m=Array(25).fill(1);m[0]=5;return this.evaluate(board,bet,m);}
 bonusDemoSpin(bet:number){return this.prepareBonusPurchase(bet,socialSeed(1920));}
}
