import {ExpansionSlot,Geometry} from './ExpansionCore';
import {ExpansionSpec} from './ExpansionCatalog';
import {PEAK_MODEL,peakOrdinary,peakUniform} from './PeakMath';
/** Local five-line adaptation: participating bear WILD opens ten independent free games. */
export class WhitePeakSlot extends ExpansionSlot {
 private drawingFree=false;
 unit(symbol:number,count:number){return (.025+.015*(8-symbol))*Math.pow(2,Math.max(0,count-3));}
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){
  if(!this.bets.includes(bet)||g.columns!==5||g.rows!==3)throw Error('Invalid peak wager or geometry');
  const high=this.drawingFree?PEAK_MODEL.freeHighByBet[bet]:PEAK_MODEL.baseHighByBet[bet],bear=this.drawingFree?PEAK_MODEL.freeBear:PEAK_MODEL.baseBearByBet[bet];
  const board=Array.from({length:15},()=>this.id(peakOrdinary(high,rng)));
  if(peakUniform(rng)<bear)board[Math.floor(peakUniform(rng)*15)]=this.id('wild');return board;
 }
 constructor(spec:ExpansionSpec){super(spec);this.config.symbols.find(s=>s.id===this.id('scatter'))!.weight=0;}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-polar';}
 get bonusSymbol(){return this.id('wild');}
 private qualifying(board:string[],bet:number){return Array.from(new Set(this.evaluate(board,bet).wins.flatMap(w=>w.cells).filter(c=>board[c]===this.id('wild'))));}
 private freeGames(base:ReturnType<ExpansionSlot['ordinary']>,bet:number,rng:()=>number){const saved=this.drawingFree;this.drawingFree=true;try{const rounds=[base];for(let left=9;left>=0;left--){const b=this.draw(bet,rng),r=this.ordinary(b,bet);r.freeSpinsRemaining=left;rounds.push(r);}return this.finish(rounds,{freeSpinsAwarded:10,featureOnly:false});}finally{this.drawingFree=saved;}}
 play(board:string[],bet:number,rng:()=>number){const base=this.ordinary(board,bet),bears=this.qualifying(board,bet);if(!bears.length)return this.finish([base]);base.expansionFeature!.frames.push(this.frame(board,'trigger','당첨 라인 흰 곰 · 무료 10회',bears));return this.freeGames(base,bet,rng);}
 prepareBonusPurchase(_bet:number,_rng:()=>number):never{throw Error('White Peak free10 cannot support a 100-bet purchase: maximum 30 bets');}
}
