/** Audit metadata must never mutate a shared registered engine. */
export function withAuditCase(slot:SlotMain,auditCase:string,auditControl:string){
 return Object.assign(Object.create(slot) as SlotMain,{auditCase,auditControl});
}

function auditNaturalEngine(slot:SlotMain,params:URLSearchParams){
 const naturalSpin=slot.spin.bind(slot),outcome=params.get('audit-outcome');
 if(outcome==='no-win'||outcome==='multi-win'||outcome==='duel')slot.demoSpin=bet=>{
  let seed=722091;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
  for(let attempt=0;attempt<10000;attempt++){
   const result=naturalSpin(bet,rng);
   if(!result.rounds&&(outcome==='no-win'?result.wins.length===0:outcome==='duel'?!!result.gladiatorFeature&&result.wins.length>0:result.wins.length>1))return result;
  }
  throw Error('Natural audit outcome not found: '+slot.config.id);
 };
 return applyHitRatePolicy(slot);
}
function gladiatorAuditEngine(params:URLSearchParams){
 const slot=new GladiatorSlot();
 if(params.get('audit-gladiator-bonus')==='beast'){const bonus=slot.bonusDemoSpin.bind(slot);slot.bonusDemoSpin=bet=>bonus(bet,'beast');}
 return auditNaturalEngine(slot,params);
}
export const RHINO_AUDIT_SEEDS={retrigger:3145123970,cap:2703636428};
function rhinoAuditEngine(params:URLSearchParams){
 const slot=new RhinoSlot(),kind=params.get('audit-rhino-case');
 const rngFor=(initial:number)=>{let seed=initial;return()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};};
 // Saved states before complete, unmodified source-engine calls. These rare
 // local QA cases neither inject boards nor rewrite awards or production RNG.
 if(kind==='retrigger')slot.bonusDemoSpin=bet=>{
  const result=slot.spin(bet,rngFor(RHINO_AUDIT_SEEDS.retrigger));
  if(!result.rounds?.some(round=>round.freeSpinsAdded===5))throw Error('Stale Rhino retrigger audit seed');
  return result;
 };
 if(kind==='cap')slot.prepareBonusPurchase=bet=>{
  const result=slot.prepareBonusPurchaseMode(bet,2,rngFor(RHINO_AUDIT_SEEDS.cap));
  if(result.payout!==bet*slot.maxWin)throw Error('Stale Rhino cap audit seed');
  return result;
 };
 return auditNaturalEngine(slot,params);
}
export const TIGER_AUDIT_CASES:Record<string,{seed:number;state:number[];tier:number}>={tier0:{seed:3265772847,state:[0,3],tier:0},unlock:{seed:4104819542,state:[0,9],tier:1},tier1:{seed:3945032478,state:[1,4],tier:1},tier2:{seed:1826259653,state:[2,0],tier:2},tier3:{seed:4019377550,state:[3,0],tier:3}};
function tigerAuditEngine(params:URLSearchParams){
 const slot=new PolarTigerSlot(EXPANSION_SPECS.find(spec=>spec.id==='polar-tiger-path')!),kind=params.get('audit-tiger-case')||params.get('audit-outcome');
 if(kind&&TIGER_AUDIT_CASES[kind]){const spin=(bet:number)=>{const saved=TIGER_AUDIT_CASES[kind];slot.setProgress({[slot.config.id+':'+bet]:saved.state});let seed=saved.seed;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},result=slot.spin(bet,rng),entry=result.rounds?.[0]??result;if(entry.expansionFeature?.frames[0].growth?.level!==saved.tier||kind!=='unlock'&&!result.rounds)throw Error('Stale Tiger audit seed');return result;};if(kind==='unlock')slot.demoSpin=spin;else slot.bonusDemoSpin=spin;}
 return auditNaturalEngine(slot,params);
}
export const PARIS_AUDIT_SEED=10799961;
function parisAuditEngine(params:URLSearchParams){
 const slot=new PuppyParisSlot(EXPANSION_SPECS.find(spec=>spec.id==='puppy-paris-path')!);
 slot.bonusDemoSpin=bet=>{let seed=PARIS_AUDIT_SEED;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},result=slot.spin(bet,rng);if(!result.featureChoices)throw Error('Stale Paris audit seed');return result;};
 return auditNaturalEngine(slot,params);
}
