export const WOLF_AUDIT_SEEDS:Record<string,number>={money:3601869780,bonus:3435103394,nested:3435103394,retrigger:1294937666};
function wolfAuditEngine(params:URLSearchParams){
 const slot=new WolfSlot(),raw=slot.spin.bind(slot);
 const find=(bet:number,kind:string)=>{
  // Offline search saved the RNG state before complete natural spins. This
  // avoids blocking the UI on millions of spins for rare nested/retrigger cases.
  const seeds=WOLF_AUDIT_SEEDS;
  let seed=seeds[kind]??96220922;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
  for(let attempt=0;attempt<(seeds[kind]===undefined?100000:1);attempt++){
   const result=raw(bet,rng),free=result.rounds;
   if(kind==='money'?!free&&!!result.wolfMoneyFeature:kind==='nested'?free?.slice(1).some(round=>round.wolfMoneyFeature):kind==='retrigger'?free?.some(round=>round.freeSpinsAdded):!!free)return result;
  }
  throw Error('Natural Wolf audit outcome not found: '+kind);
 };
 if(params.get('audit-outcome')==='money')slot.demoSpin=bet=>find(bet,'money');
 slot.bonusDemoSpin=bet=>find(bet,params.get('audit-wolf-bonus')||'bonus');
 return auditNaturalEngine(slot,params);
}

/** Only called from isolated local playback. Explicit fixture requests remain
 * fixtures after lobby promotion; an unqualified visible slot uses its real
 * registered engine. This registry never changes ownership or lobby exposure. */
export function resolveAuditSlots(visible:SlotMain[],ids:string[],params:URLSearchParams):SlotMain[]{
 const drafts=new Map(schematicDraftSlots(ids,params).map(slot=>[slot.config.id,slot]));
 return [...Array.from(new Set(ids))].map(id=>{
  if(id==='red-cloak-expedition')return redCloakAudit(params);
  if(id==='gem-cannon-theatre')return gemCannonAudit(params);
  if(id==='frog-crown-pond')return frogCrownAudit(params);
  const frogStory=frogStoryInputAudit(id,params);if(frogStory)return frogStory;
  const dragon=dragonInputAudit(id,params);if(dragon)return dragon;
  const cruise=cruiseInputAudit(id,params);if(cruise)return cruise;
  const bear=bearInputAudit(id,params);if(bear)return bear;
  const thunder=thunderInputAudit(id,params);if(thunder)return thunder;
  const strategy=strategyInputAudit(id,params);if(strategy)return strategy;
  const mask=amberMaskAudit(id,params);if(mask)return mask;
  const harvestGap=gapHarvestAudit(id,params);if(harvestGap)return harvestGap;
  const fixedGap=gapFixedAudit(id,params);if(fixedGap)return fixedGap;
  const addition2230=social2230Audit(id,params);if(addition2230)return addition2230;
  if(id==='vault-multiplier-workshop'){const vault=new VaultWorkshopSlot(),kind=params.get('audit-outcome');if(kind==='no-win'||kind==='regular'||kind==='one-stamp'||kind==='no-stamp')vault.demoSpin=bet=>{let seed=19;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let n=0;n<10000;n++){const r=vault.spin(bet,rng),count=r.vaultFeature?.multipliers.filter(v=>v>0).length;if(kind==='no-win'?r.payout===0:kind==='regular'?r.payout>0&&!r.vaultFeature:kind==='one-stamp'?count===1:count===0)return r;}throw Error('Vault audit outcome unavailable');};return vault;}
  if(id==='sugar-lane-rush')return socialAdditionAudit(new SugarLaneSlot(),params);
  if(id==='moonlight-monster-show')return socialAdditionAudit(new MonsterShowSlot(),params);
  if(id==='ace-target-club')return aceTargetAudit(params);
  if(id==='balloon-bundle-festival')return balloonBundleAudit(params);
  if(id==='bronze-guard-march')return bronzeGuardAudit(params);
  if(id==='stargem-appraisal')return stargemAudit(params);
  if(id==='blackout-restoration')return blackoutAudit(params);
  if(id==='seven-jewel-dig')return sevenJewelAudit(params);
  if(id==='tenth-bell-sheriff')return tenthBellAudit(params);
  if(id==='golden-city-atlas')return goldenAtlasAudit(params);
  if(id==='white-peak-impact')return whitePeakAudit(params);
  if(id==='sun-goddess-stack')return sunGoddessAudit(params);
  if(id==='joey-puzzle-trail')return joeyAudit(params);
  if(id==='feline-double-trails')return felineAudit(params);
  if(id==='wolf-stack-ridge')return wolfStackAudit(params);
  if(id==='serpent-gaze-reels')return gazeAudit(params);
  if(id==='cat-diamond-promotion')return catPromotionAudit(params);
  if(id==='crystal-seal-breaker')return crystalSealAudit(params);
  if(id==='oathblade-order')return oathbladeAudit(params);
  if(id==='toy-defenders')return toyDefendersAudit(params);
  if(id==='night-park-board')return nightParkAudit(params);
  if(id==='triple-compass')return compassAudit(params);
  if(id==='neon-band-mixer')return neonBandAudit(params);
  if(id==='lantern-bridge')return lanternBridgeAudit(params);
  if(id==='walnut-toy-workshop')return walnutWorkshopAudit(params);
  if(id==='full-moon-keep')return socialAdditionAudit(new FullMoonKeepSlot(),params);
  const registered=visible.find(slot=>slot.config.id===id);
  const mode=(name:string,fallback:string)=>params.get('audit-'+name)||fallback;
  if(id==='city-linked-prize'&&params.has('audit-city-case'))return cityAuditEngine(params);
  if(id==='relic-discovery-ledger'&&params.has('audit-relic-case'))return relicAuditEngine(params);
  if(id==='polar-tiger-path'&&(params.has('audit-tiger-case')||TIGER_AUDIT_CASES[params.get('audit-outcome')||'']))return tigerAuditEngine(params);
  if(id==='puppy-paris-path'&&(params.has('audit-paris-case')||params.get('audit-outcome')==='journey'))return parisAuditEngine(params);
  if(id==='heart-link-vault'&&(params.has('audit-heart-case')||HEART_AUDIT_SEEDS[params.get('audit-outcome')||'']!==undefined))return heartAuditEngine(params);
  if(id==='nile-queen-double'&&(params.has('audit-nile-case')||NILE_AUDIT_SEEDS[params.get('audit-outcome')||'']!==undefined))return nileAuditEngine(params);
  if(id==='rhino-grand-ways')return params.get('audit-rhino')==='engine'?rhinoAuditEngine(params):params.has('audit-rhino')||!registered?new RhinoPreviewSlot(mode('rhino','chain')):registered;
  if(id==='hunter-book-tutu')return params.get('audit-tut')==='engine'?applyHitRatePolicy(new TutSlot()):params.has('audit-tut')||!registered?new TutPreviewSlot(mode('tut','expansion')):registered;
  if(id==='wolf-gold-moon')return params.get('audit-wolf')==='engine'?wolfAuditEngine(params):params.get('audit-wolf')==='nested'?new WolfNestedPreviewSlot():params.has('audit-wolf')||!registered?new WolfPreviewSlot(mode('wolf','standard')):registered;
  if(id==='chaos-crew-x')return params.get('audit-chaos')==='engine'?auditNaturalEngine(new ChaosSlot(),params):params.has('audit-chaos')||!registered?new ChaosPreviewSlot(mode('chaos','bonus')):registered;
  if(id==='gladiator-lore')return params.get('audit-gladiator')==='engine'?gladiatorAuditEngine(params):params.has('audit-gladiator')||!registered?new GladiatorPreviewSlot(mode('gladiator','arena')):registered;
  if(drafts.has(id))return drafts.get(id)!;
  if(registered)return registered;
  switch(id){
   case 'boot-camp-x':return new SubmarinePreviewSlot(mode('submarine','pack'));
   case 'serial-kitchen':return new SerialPreviewSlot(mode('serial','hold'));
   case 'caesar-cat-palace':return new KittenPreviewSlot(mode('kitten','yarn'));
   case 'double-down-street':return new HogsPreviewSlot(mode('hogs','remix'));
   case 'road-rage-x':return new RoadPreviewSlot(mode('road','collision'));
   case 'viking-runecrafty':return new VikingPreviewSlot(mode('viking','ordinary'));
   default:throw Error('Unknown isolated audit slot: '+id);
  }
 });
}

function socialAdditionAudit(slot:SlotMain,params:URLSearchParams){
 const outcome=params.get('audit-outcome');
 // Recorded RNG state before a complete natural retrigger round; no forced symbols.
 const find=(bet:number,kind:string)=>{let seed=kind==='retrigger'&&slot.config.id==='full-moon-keep'?3402153272:20260927;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let n=0;n<100000;n++){const r=slot.spin(bet,rng);if(kind==='retrigger'?r.rounds?.some(q=>q.freeSpinsAdded):kind==='bonus'?!!r.rounds:!r.rounds&&(kind==='no-win'?r.payout===0:r.wins.length>1))return r;}throw Error('Social audit outcome unavailable: '+kind);};
 if(outcome==='no-win'||outcome==='multi-win')slot.demoSpin=bet=>find(bet,outcome);
 slot.bonusDemoSpin=bet=>find(bet,outcome==='retrigger'?'retrigger':'bonus');
 return slot;
}
