import {Cascade,SpinResult,Win} from './SlotMain';

export const BANDIT_TIERS=[5,6,7,8,9,11,13];
export const BANDIT_PAYS=[
 [1,1.5,2,3,10,30,100],
 [.5,.7,1,1.5,5,15,50],[.5,.7,1,1.5,5,15,50],
 [.3,.4,.5,.7,2.5,7.5,25],[.3,.4,.5,.7,2.5,7.5,25],
 ...Array.from({length:5},()=>[.1,.2,.3,.5,1.5,5,15]),
];
export function banditPay(symbol:number,count:number){
 let tier=-1;BANDIT_TIERS.forEach((minimum,i)=>{if(count>=minimum)tier=i;});
 return tier<0?0:BANDIT_PAYS[symbol]?.[tier]||0;
}
export type GoldenKind='bronze'|'silver'|'gold'|'clover'|'pot';
export interface GoldenPrize {cell:number;kind:GoldenKind;value:number;factor:number;}
export interface GoldenWave {
 reveal:GoldenPrize[];
 carried:GoldenPrize[];
 clovers:{cell:number;factor:number;changes:{cell:number;before:number;after:number;factorOnly:boolean}[]}[];
 collections:{cell:number;factor:number;sources:{cell:number;value:number}[];value:number}[];
 after:GoldenPrize[];
}
export interface GoldenFeature {cells:number[];waves:GoldenWave[];final:GoldenPrize[];award:Win;}
export interface BanditContext {
 id:string;bet:number;limit:number;golden:number[];retain:'none'|'until-rainbow'|'bonus';
 pick:()=>string;reveal:(cell:number,wave:number)=>{kind:GoldenKind;value:number};
}
const copy=(prizes:GoldenPrize[])=>prizes.map(prize=>({...prize}));
const adjacent=(a:number,b:number)=>a!==b&&Math.abs(a%6-b%6)<=1&&Math.abs(Math.floor(a/6)-Math.floor(b/6))<=1;

/** Values are conserved through collection: consumed coins/pots are not paid twice. */
export function goldenFeature(context:BanditContext,cells:number[]):GoldenFeature {
 const waves:GoldenWave[]=[];let carried:GoldenPrize[]=[];
 const max=context.limit/context.bet;
 for(let wave=0;wave<256;wave++){
  const reveal=cells.filter(cell=>!carried.some(p=>p.cell===cell)).map(cell=>{
   const prize=context.reveal(cell,wave);return{cell,kind:prize.kind,value:prize.kind==='pot'?0:prize.value,factor:1};
  });
  const current=[...copy(carried),...copy(reveal)].sort((a,b)=>a.cell-b.cell);
  const event:GoldenWave={reveal:copy(reveal),carried:copy(carried),clovers:[],collections:[],after:[]};
  for(const clover of current.filter(p=>p.kind==='clover')){
   const changes:GoldenWave['clovers'][number]['changes']=[];
   for(const target of current.filter(p=>p.kind!=='clover'&&adjacent(clover.cell,p.cell))){
    const factorOnly=target.kind==='pot'&&target.value===0,before=factorOnly?target.factor:target.value;
    const after=Math.min(max,before*clover.value);if(factorOnly)target.factor=after;else target.value=after;
    changes.push({cell:target.cell,before,after,factorOnly});
   }
   event.clovers.push({cell:clover.cell,factor:clover.value,changes});
  }
  const newPots=reveal.filter(p=>p.kind==='pot').map(p=>p.cell).sort((a,b)=>a-b);
  for(const cell of newPots){
   const pot=current.find(p=>p.cell===cell)!;
   const sources=current.filter(p=>p.cell!==cell&&p.kind!=='clover'&&p.value>0).map(p=>({cell:p.cell,value:p.value}));
   pot.value=Math.min(max,Math.round(sources.reduce((n,p)=>n+p.value,0)*pot.factor*10)/10);
   for(const source of sources)current.find(p=>p.cell===source.cell)!.value=0;
   event.collections.push({cell,factor:pot.factor,sources,value:pot.value});
  }
  event.after=copy(current);waves.push(event);
  const total=current.filter(p=>p.kind!=='clover').reduce((n,p)=>n+p.value,0);
  if(!newPots.length||total>=max){
   const final=copy(current.filter(p=>p.kind!=='clover'&&p.value>0));
   const award:Win={line:-1,symbol:context.id+'-rainbow',cells:final.map(p=>p.cell),amount:Math.min(context.limit,Math.round(total*context.bet))};
   return{cells:[...cells],waves,final,award};
  }
  // Only the last collecting pot carries its stored value into the next reveal.
  carried=copy(current.filter(p=>p.cell===newPots[newPots.length-1]));
 }
 throw Error('Golden Squares did not converge');
}

export function banditRound(context:BanditContext,opening?:string[]):SpinResult {
 const {id,bet,pick,limit}=context,wild=id+'-wild';
 let board=opening?[...opening]:Array.from({length:30},pick),paid=0;
 const golden=new Set(context.golden),cascades:Cascade[]=[],wins:Win[]=[];
 for(let step=0;step<1024;step++){
  const stageWins:Win[]=[];
  for(let symbol=0;symbol<10;symbol++){
   const seen=new Set<number>(),name=id+'-'+symbol;
   for(let start=0;start<30;start++){
    if(seen.has(start)||board[start]!==name)continue;
    const cells:number[]=[],pending=[start];seen.add(start);
    while(pending.length){const at=pending.pop()!;cells.push(at);for(const to of [at-6,at+6,...(at%6?[at-1]:[]),...(at%6<5?[at+1]:[])]){
     if(to<0||to>=30||seen.has(to)||(board[to]!==name&&board[to]!==wild))continue;seen.add(to);pending.push(to);
    }}
    const amount=Math.min(limit-paid,Math.round(bet*banditPay(symbol,cells.length)));
    if(amount>0){stageWins.push({line:-1,symbol:name,cells,amount});paid+=amount;}
   }
  }
  const winningTypes=new Set(stageWins.map(w=>w.symbol)),removed=new Set(stageWins.flatMap(w=>w.cells));
  board.forEach((symbol,cell)=>{if(winningTypes.has(symbol))removed.add(cell);});
  const stage:Cascade={board:[...board],wins:stageWins,payout:stageWins.reduce((n,w)=>n+w.amount,0),multiplier:1,cellMultipliers:Array(30).fill(0),nextMultipliers:Array(30).fill(0),goldenCells:[...Array.from(golden)],drops:[],removedCells:[...Array.from(removed)]};
  for(const cell of stageWins.flatMap(w=>w.cells))golden.add(cell);stage.nextGoldenCells=[...Array.from(golden)];
  cascades.push(stage);wins.push(...stageWins);
  if(!removed.size||paid>=limit)break;
  const next=Array<string>(30);
  for(let col=0;col<6;col++){
   const kept=Array.from({length:5},(_,row)=>row*6+col).filter(cell=>!removed.has(cell)),incoming=5-kept.length;
   for(let row=0;row<5;row++){const to=row*6+col,from=row<incoming?-1:kept[row-incoming];next[to]=from<0?pick():board[from];stage.drops.push({from:from<0?(row-incoming)*6+col:from,to,symbol:next[to]});}
  }
  board=next;if(step===1023)throw Error('Bandit cascade did not converge');
 }
 const activated=board.includes(id+'-rainbow')&&golden.size>0&&paid<limit;
 const feature=activated?goldenFeature({...context,limit:limit-paid},[...Array.from(golden)].sort((a,b)=>a-b)):undefined;
 if(feature?.award.amount)wins.push(feature.award);
 const keep=context.retain==='bonus'||context.retain==='until-rainbow'&&!activated;
 return{board,bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),cascades,goldenCells:[...Array.from(golden)],nextGoldenCells:keep?[...Array.from(golden)]:[],goldenFeature:feature};
}
