import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';import {BET_LEVELS} from './BetLevels';import {WOLF_LINES} from './WolfRules';import {STARGEM_MODEL as M,stargemUniform,stargemOrdinary} from './StargemMath';import {socialPresentation,awardLines,packRounds} from './Social2230Rules';
export const STARGEM_ID='stargem-appraisal';
export const STARGEM_PAYS=[[1.2,3.2,8],[1,2.4,6],[.8,2,4.8],[.6,1.6,4],[.4,1.2,3.2],[.4,1,2.4],[.4,.8,2],[.4,.8,1.6]];
export interface StargemMoney {cell:number;win:Win;}
export interface StargemPlayback {lineWins:Win[];money:StargemMoney[];free:boolean;}
export const stargemFree=(count:number)=>count>=5?25:count===4?15:count===3?7:0;
export class StargemSlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];readonly usesLocalPayouts=true;readonly maxWin=10000;readonly hasBonus=true;readonly bonusCalibrationKey=STARGEM_ID+':independent-money-v1';get bonusSymbol(){return STARGEM_ID+'-scatter';}
 readonly presentation=socialPresentation('당첨선과 무관하게 보석 표기액 지급','별보석 무료 감정');
 readonly config:SlotConfig={id:STARGEM_ID,title:'별보석 감정소',subtitle:'STARGEM APPRAISAL',tag:'INDEPENDENT MONEY WILD',color:'#343448',accent:'#b3e2db',description:'5×3 · 25라인 · 왼쪽부터3개 이상\n별보석 WILD는 일반 심볼을 대체하며 모든 위치에서 표기액을 별도로 지급합니다.\n라인 당첨에 쓰이지 않은 보석도 지급하며 보석당 한 번만 수집합니다.\n감정 증서3/4/5개: 무료7/15/25회. 무료 중에도 같은 재진입, 총100회 상한.\n보석 그림은 남고 금액만 합계로 이동.',symbols:['보석 저울','감정 확대경','벨벳 보석함','은색 핀셋','보라 원석','진주 목걸이','세공 망치','보석 반지','별보석 WILD','감정 증서'].map((name,i)=>({id:STARGEM_ID+'-'+(i===8?'wild':i===9?'scatter':i),name,color:'#b3e2db',weight:[5,6,7,8,10,12,14,16,1.7,2][i],payout:i<8?STARGEM_PAYS[i][2]:0}))};
 evaluate(board:string[],bet:number,rng:()=>number=()=>.5,free=false):SpinResult{if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!this.config.symbols.some(t=>t.id===s)))throw Error('Invalid stargem board');const lineWins=awardLines(this.config,board,bet,STARGEM_PAYS),money=board.flatMap((s,cell)=>s===STARGEM_ID+'-wild'?[{cell,win:{line:-1,symbol:s,cells:[cell],amount:Math.round(bet*[.1,.2,.5,1,2][Math.floor(stargemUniform(rng)*5)])}}]:[]),wins=[...lineWins,...money.map(m=>m.win)];return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),stargemFeature:{lineWins,money,free},presentation:this.presentation};}
 private grid(bet:number,rng:()=>number,free=false,conditional=false){if(!this.bets.includes(bet))throw Error('Invalid Stargem bet');const q=free?M.freeGate:M.gate,h=free?M.freeHighByBet[bet]:M.highByBet[bet],wild=free?M.freeWild:M.baseWild,board=Array.from({length:15},()=>STARGEM_ID+'-'+stargemOrdinary(h,wild,rng));let flags=0;
  if(conditional){const options:Array<{mask:number;mass:number}>=[];let total=0;for(let mask=0;mask<32;mask++){const n=mask.toString(2).replace(/0/g,'').length;if(n<3)continue;const mass=q**n*(1-q)**(5-n);options.push({mask,mass});total+=mass;}let pick=stargemUniform(rng)*total;flags=options[options.length-1].mask;for(const o of options){pick-=o.mass;if(pick<0){flags=o.mask;break;}}}else for(let col=0;col<5;col++)if(stargemUniform(rng)<q)flags|=1<<col;
  for(let col=0;col<5;col++)if(flags&(1<<col))board[Math.floor(stargemUniform(rng)*3)*5+col]=this.bonusSymbol;return board;
 }
 private draw(bet:number,rng:()=>number,free=false){return this.evaluate(this.grid(bet,rng,free),bet,rng,free);}
 private sequence(base:SpinResult,rng:()=>number):SpinResult{const initial=stargemFree(base.board.filter(s=>s===this.bonusSymbol).length);if(!initial)return base;const rounds=[base];let remaining=initial,awarded=initial,played=0,paid=base.payout;while(remaining>0&&paid<base.bet*this.maxWin){remaining--;played++;const r=this.draw(base.bet,rng,true);let left=base.bet*this.maxWin-paid;for(const w of r.wins){w.amount=Math.min(w.amount,left);left-=w.amount;}r.payout=r.wins.reduce((n,w)=>n+w.amount,0);paid+=r.payout;const extra=Math.min(stargemFree(r.board.filter(s=>s===this.bonusSymbol).length),100-awarded);remaining+=extra;awarded+=extra;r.freeSpinsAdded=extra||undefined;r.freeSpinsRemaining=remaining;r.roundLabel='보석 무료 '+played+' · 남은 '+remaining+'회';rounds.push(r);}return packRounds(rounds,{freeSpinsAwarded:initial,featureName:'별보석 무료 감정',presentation:this.presentation,bonusEndReason:paid>=base.bet*this.maxWin?'max-win':'spins-exhausted'});}
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.sequence(this.draw(bet,rng),rng);}
 prepareBonusPurchase(bet:number,rng:()=>number):SpinResult{const base:SpinResult={board:this.grid(bet,rng,false,true),bet,wins:[],payout:0,presentation:this.presentation},r=this.sequence(base,rng),rounds=r.rounds!.slice(1);return packRounds(rounds,{freeSpinsAwarded:r.freeSpinsAwarded,featureName:r.featureName,presentation:r.presentation,bonusEndReason:r.bonusEndReason,bonusTriggerRound:base});}
 demoSpin(bet:number){return this.find(bet,false);}bonusDemoSpin(bet:number){return this.find(bet,true);}private find(bet:number,bonus:boolean){let seed=400928;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<100000;i++){const r=this.spin(bet,rng);if(bonus?!!r.rounds:!r.rounds&&r.payout>0)return r;}throw Error('Stargem fixture unavailable');}
}
