import {BET_LEVELS} from './BetLevels';
import {BRIDGE_MODEL as M,bridgeUniform,bridgeOrdinary} from './LanternBridgeMath';
import {SlotMain,SlotConfig,SpinResult,SlotPresentation} from './SlotMain';
import {WOLF_LINES} from './WolfRules';
import {social1921Pays,validateSocialBoard,lineAwards,totalAwards,socialSeed} from './Social1921Rules';
export const BRIDGE_ID='lantern-bridge';
export interface BridgePlayback {before:string[];after:string[];bridges:{row:number;from:number;to:number;cells:number[]}[];free:boolean;}
/** Source confirms conversion between wilds. Same-row geometry, protected
 * scatters, 8/+4 spins and ×2 free wins are explicit local adaptations. */
export class LanternBridgeSlot extends SlotMain {
 readonly usesLocalPayouts=true;readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];readonly hasBonus=true;readonly maxWin=10000;
 readonly bonusCalibrationKey=BRIDGE_ID+':bridge-v1';get bonusSymbol(){return BRIDGE_ID+'-scatter';}
 readonly presentation:SlotPresentation={evidence:'source-title-pending',anticipationText:'등불 사이에 다리를 놓습니다',triggerText:'야간 다리 개방',bonusInText:'8회 · 연결 당첨 두 배',hitText:'등불 사이 WILD 변환',totalWinText:'다리 총 보상',signature:'같은 행 두 등불 사이 변환',uiEffect:'양끝 점등 → 내부 변환 → 한 번 판정',soundCue:'featureLand',anticipationHold:.3,hitHold:.25,outHold:.4};
 readonly config:SlotConfig={id:BRIDGE_ID,title:'두 등불의 다리',subtitle:'TWIN LANTERN BRIDGE',tag:'WILD BRIDGE',color:'#273c46',accent:'#f0c27e',description:'5×3 · 25라인 · 왼쪽부터 3개 이상\n같은 행의 양끝 등불 WILD 사이를 WILD로 바꿉니다.\n통행패 SCATTER는 변환하지 않습니다.\n변환 완료 후 한 번만 당첨 판정합니다.\n통행패 3개 이상: 무료 8회, WILD 포함 당첨 ×2\n무료 중 통행패 3개 이상: +4회\n무료 회전은 최대1000회까지 진행합니다.',symbols:['다리 문장','나룻배','기와 지붕','차 주전자','접부채','비단 매듭','수련','풍경종','등불 WILD','통행패'].map((name,n)=>({id:BRIDGE_ID+'-'+(n===8?'wild':n===9?'scatter':n),name,color:'#f0c27e',weight:[5,6,7,8,10,12,14,16,2.5,3][n],payout:n<8?social1921Pays(BRIDGE_ID)[n][2]:0}))};
 evaluate(board:string[],bet:number,free=false):SpinResult{
  validateSocialBoard(this.config,board,bet,this.bets,15);const after=[...board],bridges:BridgePlayback['bridges']=[];
  for(let row=0;row<3;row++){const ends=Array.from({length:5},(_,col)=>row*5+col).filter(c=>board[c]===BRIDGE_ID+'-wild');if(ends.length<2)continue;const from=ends[0],to=ends[ends.length-1],cells:number[]=[];for(let c=from+1;c<to;c++)if(board[c]!==this.bonusSymbol&&board[c]!==BRIDGE_ID+'-wild'){after[c]=BRIDGE_ID+'-wild';cells.push(c);}if(cells.length)bridges.push({row,from,to,cells});}
  const wins=lineAwards(BRIDGE_ID,after,bet);
  // A wild beyond the winning prefix must not multiply that line.
  for(const win of wins)if(free&&win.cells.some(c=>after[c]===BRIDGE_ID+'-wild')){win.amount*=2;win.multiplier!*=2;}
  return totalAwards({board:after,openingBoard:[...board],bet,wins,payout:0,bridgeFeature:{before:[...board],after:[...after],bridges,free},presentation:this.presentation});
 }
 private grid(bet:number,rng:()=>number,free:boolean,conditional=false){if(!this.bets.includes(bet))throw Error('Invalid Bridge bet');const q=free?M.freeGate:M.gate,w=free?M.freeWild:M.baseWild,h=(free?M.freeHighByBet:M.highByBet)[bet],board=Array.from({length:15},()=>{const regular=bridgeOrdinary(h,rng);return BRIDGE_ID+'-'+(bridgeUniform(rng)<w?'wild':regular);});let flags=0;
  if(conditional){const options:{mask:number;mass:number}[]=[];let total=0;for(let mask=0;mask<32;mask++){const n=mask.toString(2).replace(/0/g,'').length;if(n<3)continue;const mass=q**n*(1-q)**(5-n);options.push({mask,mass});total+=mass;}let roll=bridgeUniform(rng)*total;flags=options[options.length-1].mask;for(const o of options){roll-=o.mass;if(roll<0){flags=o.mask;break;}}}else for(let col=0;col<5;col++)if(bridgeUniform(rng)<q)flags|=1<<col;
  for(let col=0;col<5;col++)if(flags>>col&1)board[Math.floor(bridgeUniform(rng)*3)*5+col]=this.bonusSymbol;return board;
 }
 private round(bet:number,rng:()=>number,free:boolean){return this.evaluate(this.grid(bet,rng,free),bet,free);}
 private sequence(base:SpinResult,rng:()=>number){let awarded=0;const result=this.freeSpinSequence(base,()=>this.round(base.bet,rng,true),r=>{if(r.board.filter(id=>id===this.bonusSymbol).length<3)return 0;const add=Math.min(r===base?8:4,1000-awarded);awarded+=add;return add;});if(result.rounds){result.presentation=this.presentation;result.featureName='야간 다리 무료 회전';result.bonusEndReason=result.payout>=base.bet*this.maxWin?'max-win':'spins-exhausted';}return result;}
 spin(bet:number,rng:()=>number=Math.random){return this.sequence(this.round(bet,rng,false),rng);}
 prepareBonusPurchase(bet:number,rng:()=>number){const board=this.grid(bet,rng,false,true),base:SpinResult={board,bet,wins:[],payout:0,presentation:this.presentation};const result=this.sequence(base,rng);result.bonusTriggerRound=base;result.rounds=result.rounds!.slice(1);result.wins=result.rounds.flatMap(r=>r.wins);return totalAwards(result);}
 demoSpin(bet:number){const board=Array.from({length:15},(_,i)=>BRIDGE_ID+'-'+i%8);board[5]=board[9]=BRIDGE_ID+'-wild';return this.evaluate(board,bet);}
 bonusDemoSpin(bet:number){return this.prepareBonusPurchase(bet,socialSeed(1921));}
}
