import type {Win} from '../slots/SlotMain';
/** Group settled awards without recomputing or rounding their value. */
export function nileAwardGroups(wins:Win[],board:string[],wild:string,scatter:string,free:boolean){
 const groups:{kind:'substitute'|'queenFive'|'queen'|'scatter'|'normal';multiplier:number;wins:Win[];wildCells:number[];amount:number}[]=[];
 for(const win of wins){
  const wildCells=win.cells.filter(c=>board[c]===wild),kind=win.symbol===scatter?'scatter':win.symbol===wild?(win.cells.length===5?'queenFive':'queen'):wildCells.length?'substitute':'normal';
  const multiplier=kind==='scatter'?(free?3:1):win.multiplier??(free?3:1);
  let group=groups.find(g=>g.kind===kind&&g.multiplier===multiplier);
  if(!group){group={kind,multiplier,wins:[],wildCells:[],amount:0};groups.push(group);}
  group.wins.push(win);group.amount+=win.amount;group.wildCells=Array.from(new Set([...group.wildCells,...wildCells]));
 }
 return groups;
}
