import type {PerkCondition} from '../services/CostumePerks';

export interface PerkToastTheme {background:string;border:string;text:string;}

/** Stable colors by activation rule, independent of the equipped item's color. */
export const perkToastThemes:Record<PerkCondition,PerkToastTheme>={
 hit:{background:'#173d43',border:'#73e0dd',text:'#e8ffff'},
 big:{background:'#4b3618',border:'#ffd166',text:'#fff2c2'},
 super:{background:'#17384b',border:'#67d5ff',text:'#e8f8ff'},
 mega:{background:'#342655',border:'#c7a5ff',text:'#f2eaff'},
 amazing:{background:'#4b213f',border:'#ff8fd4',text:'#ffe8f7'},
 streak2:{background:'#24401f',border:'#9dde7b',text:'#efffe5'},
 streak3:{background:'#384315',border:'#d6f06a',text:'#f9ffd9'},
 five:{background:'#203760',border:'#8fb7ff',text:'#edf4ff'},
 multi:{background:'#292a58',border:'#a9abff',text:'#f0f0ff'},
 four:{background:'#51252b',border:'#ff999f',text:'#ffedef'},
 cascade3:{background:'#4a2e1c',border:'#ffad70',text:'#fff0e4'},
 cascade5:{background:'#402454',border:'#dc94ff',text:'#f9eaff'},
 comeback:{background:'#4c2734',border:'#ff9fbc',text:'#ffedf3'},
 small:{background:'#303646',border:'#b9c4dc',text:'#f1f4fb'}
};

export function perkToastTheme(condition:PerkCondition|undefined):PerkToastTheme{return condition?perkToastThemes[condition]:{background:'#171827',border:'#fff0cb',text:'#fff0cb'};}
