import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {drawSealWindow,sealPrizeMultiplier} from './SealMath';
import {SlotProgress,normalizeSlotProgress,socialPresentation,packRounds} from './Social2230Rules';
export const SEAL_ID='crystal-seal-breaker',SEAL_FULL=32767;
/** 80 distinct 5-reel paths sampled evenly from the 3^5 possibilities. */
export const SEAL_LINES=Array.from({length:80},(_,i)=>{let code=Math.floor(i*243/80);return Array.from({length:5},(_,col)=>{const row=code%3;code=Math.floor(code/3);return row*5+col;});});
export const SEAL_PAYS=[[1.2,3.2,8],[1,2.4,6],[.8,2,4.8],[.6,1.6,4],[.4,1.2,3.2],[.4,1,2.4],[.4,.8,2],[.4,.8,1.6]];
export interface SealPlayback {stage:'break'|'prize';before:number;after:number;removed:number[];lineWins:Win[];multiplier?:number;award?:Win;}
export class CrystalSealSlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly paylines=SEAL_LINES;readonly bets=[...BET_LEVELS];readonly usesLocalPayouts=true;readonly maxWin=10000;
 private progress:SlotProgress={};setProgress(value:SlotProgress){this.progress=normalizeSlotProgress(value);}
 readonly presentation=socialPresentation('당첨 타일 파괴 · 전체 봉인 해제','수정 봉인 파괴');
 readonly config:SlotConfig={id:SEAL_ID,title:'수정 봉인 해제',subtitle:'CRYSTAL SEAL BREAKER',tag:'PERSISTENT TILE BREAK',color:'#302b4b',accent:'#b0d8de',description:'5×3 · 80라인 · 왼쪽부터3개 이상\n당첨 칸의 봉인 타일을 제거합니다. 심볼은 낙하하지 않습니다.\n15칸을 모두 제거하면 수정 하나를 골라 보상을 공개합니다.\n수정은 베팅5배 × 1/2/5 중 하나. 선택 위치별 확률은 같습니다.\n수령 뒤 타일15칸 초기화. 남은 타일은 베팅별 저장. ',symbols:['보라 수정 기둥','청록 석판','붉은 인장','은 곡괭이','탐사 지도','광산 랜턴','푸른 광석','봉인 열쇠','수정구 WILD','금 간 봉인'].map((name,i)=>({id:SEAL_ID+'-'+(i===8?'wild':i===9?'scatter':i),name,color:'#b0d8de',weight:[5,6,7,8,10,12,14,16,3,3][i],payout:i<8?SEAL_PAYS[i][2]:0}))};
 evaluate(board:string[],bet:number):SpinResult {
  if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!this.config.symbols.some(t=>s===t.id)))throw Error('Invalid seal spin');const wins:Win[]=[];
  this.paylines.forEach((line,index)=>{let best:Win|undefined;for(let s=0;s<8;s++){const cells:number[]=[];for(const c of line){if(board[c]!==SEAL_ID+'-'+s&&board[c]!==SEAL_ID+'-wild')break;cells.push(c);}if(cells.length<3)continue;const amount=Math.round(bet*SEAL_PAYS[s][cells.length-3]);if(!best||best.amount<amount)best={line:index,symbol:SEAL_ID+'-'+s,cells,amount};}if(best)wins.push(best);});return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};
 }
 resolve(board:string[],bet:number,rng:()=>number=Math.random):SpinResult {
  const base=this.evaluate(board,bet),before=this.progress[SEAL_ID+':'+bet]?.[0]??SEAL_FULL,removed=Array.from(new Set(base.wins.flatMap(w=>w.cells))).filter(c=>(before&(1<<c))!==0),after=removed.reduce((mask,c)=>mask&~(1<<c),before);
  base.sealFeature={stage:'break',before,after,removed,lineWins:base.wins};base.progressUpdate={key:SEAL_ID+':'+bet,values:[after||SEAL_FULL]};if(after)return base;
  const results=Array.from({length:3},()=>{const multiplier=sealPrizeMultiplier(rng),award:Win={line:-1,symbol:SEAL_ID+'-0',cells:[],amount:bet*5*multiplier},prize:SpinResult={board:[...board],bet,wins:[award],payout:award.amount,sealFeature:{stage:'prize',before:0,after:SEAL_FULL,removed:[],lineWins:[],multiplier,award}};return packRounds([base,prize],{featureOnly:true,progressUpdate:{key:SEAL_ID+':'+bet,values:[SEAL_FULL]},presentation:this.presentation});});
  return{...results[0],featureChoices:{title:'봉인 해제 · 수정 하나를 선택하세요',labels:['왼쪽 수정','가운데 수정','오른쪽 수정'],results,defaultIndex:0,noBonusEntry:true}};
 }
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.resolve(drawSealWindow(rng).map(s=>SEAL_ID+'-'+(s===8?'wild':s===9?'scatter':s)),bet,rng);}
 demoSpin(bet:number){let seed=350928;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<100000;i++){const r=this.spin(bet,rng);if(r.wins.length>0&&new Set(r.wins.map(w=>w.symbol)).size===1)return r;}throw Error('Seal fixture unavailable');}
}
