import {FeatureGame,Random,choose} from './FeatureKit';
import {featureDefinitions} from './FeatureDefinitions';
import {SpinResult} from './SlotMain';
export class PaperLibrarySlot extends FeatureGame {
 constructor(){super(featureDefinitions['paper-library']);}
 private roll(bet:number,rng:Random,selected=-1):SpinResult {
  const board=this.rollBoard(rng);for(let i=0;i<15;i++)if(rng()<.012)board[i]=this.wildSymbol;
  if(rng()<.018)this.scatter(board,rng);
  const r=this.evaluate(board,bet);
  if(selected>=0){const symbol=this.config.symbols[selected].id,cols=Array.from({length:5},(_,c)=>c).filter(c=>[c,c+5,c+10].some(i=>board[i]===symbol));
   if(cols.length>=3){r.openingBoard=[...board];r.expandedCells=cols.flatMap(c=>[c,c+5,c+10]);r.expandedCells.forEach(i=>r.board[i]=symbol);
    this.paylines.forEach((line,index)=>r.wins.push({line:index,symbol,cells:cols.map(c=>line[c]),amount:Math.round(bet*this.paytable[selected][cols.length-1])}));
    r.payout=r.wins.reduce((n,w)=>n+w.amount,0);r.featureText=this.config.symbols[selected].name+' 확장!';
   }
  }return r;
 }
 spin(bet:number,rng:Random=Math.random):SpinResult {
  if(!this.bets.includes(bet))throw Error('Invalid bet');const base=this.roll(bet,rng),rounds=[base];if(this.count(base.board,this.bonusSymbol)<3)return this.finish(rounds,'');
  const selected=choose([0,1,2,3,4,5,6,7],rng);let left=10;
  for(let i=0;left>0&&i<100;i++){left--;const r=this.roll(bet,rng,selected);if(this.count(r.openingBoard||r.board,this.bonusSymbol)>=3)left=Math.min(99-i,left+10);r.roundLabel=this.config.symbols[selected].name+' 확장 · 남은 '+left+'회';rounds.push(r);}
  return this.finish(rounds,'마법책 프리스핀',10);
 }
}
