export const HEART_INITIAL=.18,HEART_LANDING=.075,HEART_RANDOM_BOARD=.01;
const weights=[5,6,7,8,10,12,14,16,2],pools=new Map<HeartInput,Map<number,{high:number;weights:number[];sum:number}>>();
export function heartUniform(rng:()=>number){const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid Heart random value');return value;}
export function heartOrdinary(bet:number,rng:()=>number,input:HeartInput){const high=input.highByBet[bet]??1;let bets=pools.get(input);if(!bets){bets=new Map();pools.set(input,bets);}let pool=bets.get(bet);if(!pool||pool.high!==high){const w=weights.map((v,i)=>v*(i===0?high:1));pool={high,weights:w,sum:w.reduce((a,b)=>a+b,0)};bets.set(bet,pool);}let roll=heartUniform(rng)*pool.sum;for(let i=0;i<9;i++){roll-=pool.weights[i];if(roll<0)return i===8?'wild':i;}return 7;}
let qualified:{mask:number;end:number}[]|undefined,total=0;
/** Exact IID initial mask conditional on an original row of3+ hearts. No
 * board/win search; the finite CDF retains the source18% cell probability. */
export function heartQualifiedMask(rng:()=>number){
 if(!qualified){qualified=[];for(let mask=0;mask<32768;mask++){let held=0,legal=false;for(let row=0;row<3;row++){let count=0;for(let col=0;col<5;col++)if(mask>>(row*5+col)&1)count++;held+=count;if(count>=3)legal=true;}if(legal){total+=HEART_INITIAL**held*(1-HEART_INITIAL)**(15-held);qualified.push({mask,end:total});}}}
 const roll=heartUniform(rng)*total;let lo=0,hi=qualified.length-1;while(lo<hi){const mid=(lo+hi)>>1;if(roll<qualified[mid].end)hi=mid;else lo=mid+1;}return qualified[lo].mask;
}
