import type {SpinResult} from './SlotMain';
/** Exclude the paid trigger and presentation steps from the free-spin count.
 * Include welcome and wheel awards in the bonus total even when they are not spins. */
export function bonusCompletion(result:SpinResult,purchased:boolean){
 if(!result.rounds?.length)return null;
 const bonusRounds=purchased?result.rounds:result.rounds.slice(1),compass=bonusRounds.find(round=>round.compassFeature)?.compassFeature;
 const counted=bonusRounds.filter(round=>(!round.moonFeature||round.moonFeature.mode==='free')&&round.crossroadsFeature?.mode!=='wheel'&&(!round.parkFeature||round.parkFeature.stage==='spin')&&(!compass||(compass.mode==='free'&&!round.compassFeature)));
 if(!counted.length)return null;
 return{count:counted.length,payout:bonusRounds.reduce((sum,round)=>sum+round.payout,0)};
}
