/** Existing local royal-promotion rules, with explicit input frequencies. */
export const STONE_MODEL:{scatterPerReel:number;landing:number;newPrizeHigh:number;baseHighByBet:Record<number,number>}={"scatterPerReel":0.07924244895266355,"landing":0.075,"newPrizeHigh":17.85028859202285,"baseHighByBet":{"20":11.161169624757854,"30":11.512137210933297,"40":11.260560338666387,"50":11.47504014068942,"70":11.383571344669964,"100":11.42098013832523,"150":11.320312204550454,"200":11.360408690436692,"250":11.36107639585731,"300":11.338781178494802,"350":11.343187994482637,"400":11.360408690436692,"450":11.360745464686012,"500":11.347573086244434,"600":11.360408690436692,"700":11.351131744786695,"800":11.360408690436692,"900":11.353082466531973,"1000":11.360408690436692,"2000":11.360408690436692,"3000":11.360408690436692,"4000":11.360408690436692,"5000":11.360408690436689,"6000":11.360408690436692,"7000":11.360408690436689,"8000":11.360408690436692,"9000":11.360408690436689,"10000":11.360408690436689}};
export const STONE_WEIGHTS=[5,6,7,8,10,12,14,16,2],STONE_NEW_PRIZES=[1,2,3,5,10];
const pools=new Map<number,{high:number;weights:number[];sum:number}>();
export function stoneUniform(rng:()=>number){const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid Stone random value');return value;}
export function stoneOrdinaryInput(bet:number,rng:()=>number){
 const high=STONE_MODEL.baseHighByBet[bet]??1;let pool=pools.get(bet);
 if(!pool||pool.high!==high){const weights=STONE_WEIGHTS.map((w,i)=>w*(i===0?high:1));pool={high,weights,sum:weights.reduce((n,w)=>n+w,0)};pools.set(bet,pool);}
 let sample=stoneUniform(rng)*pool.sum;
 for(let i=0;i<pool.weights.length;i++){sample-=pool.weights[i];if(sample<0)return i===8?'wild':i;}return 7;
}
export function stoneNewPrize(rng:()=>number){let sample=stoneUniform(rng)*(4+STONE_MODEL.newPrizeHigh);for(let i=0;i<5;i++){sample-=i===4?STONE_MODEL.newPrizeHigh:1;if(sample<0)return STONE_NEW_PRIZES[i];}return 10;}
