/** Cosmetic only: fixed character strip, independent of game RNG and outcomes. */
export const LOGIN_CHARACTER_ART=[
 ['bulldog','dog-yard-original','0'],
 ['raccoon','le-raccoon-bandit','hero'],
 ['zeus','gates-of-clouds','hero'],
 ['wolf','wolf-gold-moon','wild'],
 ['buffalo','prairie-buffalo-king','0'],
 ['corgi','dog-yard-original','1'],
 ['vampire','moonlight-monster-show','0'],
 ['deer','prairie-buffalo-king','1'],
 ['dachshund','dog-yard-original','2'],
 ['pumpkin','moonlight-monster-show','2'],
 ['spaniel','dog-yard-original','3'],
 ['bat','moonlight-monster-show','3'],
].map(([id,slot,symbol])=>[id,`slot-art-low-v1/${slot}/${slot}-${symbol}`] as const);

export const LOGIN_REEL_LEAD=.6;
export const LOGIN_REEL_SPIN=1.2;
export const LOGIN_REEL_STAGGER=.18;
export const LOGIN_REEL_HOLD=2.2;
export const LOGIN_REEL_CYCLE=LOGIN_REEL_SPIN+2*LOGIN_REEL_STAGGER+LOGIN_REEL_HOLD;
const STEPS=15;
/** Continuous travel across cycles and UI reconstruction; left-to-right stops. */
export function loginReelState(time:number,reel:number,count=LOGIN_CHARACTER_ART.length){
 const elapsed=Math.max(0,time-LOGIN_REEL_LEAD),cycle=Math.floor(elapsed/LOGIN_REEL_CYCLE);
 const phase=elapsed-cycle*LOGIN_REEL_CYCLE,duration=LOGIN_REEL_SPIN+reel*LOGIN_REEL_STAGGER;
 const progress=Math.min(1,phase/duration);
 const travel=cycle*STEPS+STEPS*(1-Math.pow(1-progress,3));
 const step=Math.floor(travel),offset=travel-step;
 return {index:(step+reel*4)%count,offset,spinning:phase<duration&&time>=LOGIN_REEL_LEAD};
}
