/** Fixed independent cell labels plus at most one uniform-row SCAT per reel. */
export function gapUniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error('Invalid Gap input uniform');return u;}
export function gapRestLabel(high:number,wild:number,u:number){if(u<wild)return 'wild';const w=[6*high,7,8,10,12,14,16];let roll=(u-wild)/(1-wild)*w.reduce((a,b)=>a+b,0);for(let n=0;n<w.length;n++){roll-=w[n];if(roll<0)return String(n+1);}return '7';}
export function gapInputBoard(id:string,columns:number,zero:number,high:number,wild:number,scatter:number,rng:()=>number){
 if(!Number.isFinite(zero)||zero<0||zero>1||!Number.isFinite(high)||high<0)throw Error('Invalid Gap input parameters');
 const board=Array.from({length:columns*3},()=>{const u=gapUniform(rng);return id+'-'+(u<zero?'0':gapRestLabel(high,wild,(u-zero)/(1-zero)));});
 if(scatter>0)for(let col=0;col<columns;col++)if(gapUniform(rng)<scatter)board[Math.floor(gapUniform(rng)*3)*columns+col]=id+'-scatter';return board;
}
/** Actual base distribution conditioned on at least one fully-zero column.
 * All other columns use their finite noncharged zero/SCAT state distribution. */
export function stormConditionalBoard(id:string,zero:number,high:number,wild:number,scatter:number,rng:()=>number){
 const B=(1-scatter)*zero**3,flags:{mask:number;mass:number}[]=[];let total=0;
 for(let mask=1;mask<32;mask++){let n=0;for(let c=0;c<5;c++)n+=mask>>c&1;const mass=B**n*(1-B)**(5-n);flags.push({mask,mass});total+=mass;}
 let roll=gapUniform(rng)*total,selected=31;for(const f of flags){roll-=f.mass;if(roll<0){selected=f.mask;break;}}
 const options:{mask:number;row:number;mass:number}[]=[];for(let row=-1;row<3;row++)for(let mask=0;mask<8;mask++){if(row>=0&&(mask>>row&1)||row<0&&mask===7)continue;let mass=row<0?1-scatter:scatter/3;for(let r=0;r<3;r++)if(r!==row)mass*=mask>>r&1?zero:1-zero;options.push({mask,row,mass});}
 const board=Array(15).fill('');for(let col=0;col<5;col++){if(selected>>col&1){for(let r=0;r<3;r++)board[r*5+col]=id+'-0';continue;}let u=gapUniform(rng)*(1-B),choice=options[options.length-1];for(const o of options){u-=o.mass;if(u<0){choice=o;break;}}for(let r=0;r<3;r++)board[r*5+col]=id+'-'+(r===choice.row?'scatter':choice.mask>>r&1?'0':gapRestLabel(high,wild,gapUniform(rng)));}return board;
}
