import {Color,EffectAsset,Graphics,ImageAsset,Material,Node,Sprite,SpriteFrame,Texture2D,UIOpacity,UITransform,Vec3,Vec4,tween} from 'cc';

export const BONUS_PURCHASE_RISE_SECONDS=.08;
export const BONUS_PURCHASE_MAX_SCALE=1.04;
export const PANEL_IMPACT_SECONDS=.2;

/** A short staggered shimmer around the updated BET digits. */
export function betSparkles(target:Node){
 const bounds=target.getComponent(UITransform);if(!bounds)return;
 const cx=(.5-bounds.anchorX)*bounds.width,cy=(.5-bounds.anchorY)*bounds.height;
 const cloud=new Node('BET number shimmer');cloud.layer=target.layer;target.addChild(cloud);
 for(let i=0;i<16;i++){
  const p=new Node('BET sparkle '+i);p.layer=cloud.layer;cloud.addChild(p);p.addComponent(UITransform);
  const angle=i*Math.PI/8,x=cx+Math.cos(angle)*bounds.width*.34,y=cy+Math.sin(angle)*bounds.height*.36,size=i%3===0?5:3;
  p.setPosition(x,y);p.setScale(.2,.2,1);
  const g=p.addComponent(Graphics);g.fillColor=new Color(i%3===0?'#fff6cc':i%2?'#a7fff0':'#ffd384');
  g.moveTo(0,size);g.lineTo(size*.3,size*.3);g.lineTo(size,0);g.lineTo(size*.3,-size*.3);g.lineTo(0,-size);g.lineTo(-size*.3,-size*.3);g.lineTo(-size,0);g.lineTo(-size*.3,size*.3);g.close();g.fill();
  const alpha=p.addComponent(UIOpacity);alpha.opacity=0;
  tween(alpha).delay(i*.018).to(.09,{opacity:255}).to(.12,{opacity:120}).to(.08,{opacity:235}).to(.17,{opacity:0}).start();
  tween(p).delay(i*.018).to(.12,{scale:new Vec3(1,1,1)},{easing:'quadOut'}).to(.34,{position:new Vec3(x+Math.cos(angle)*14,y+8+Math.sin(angle)*10,0),scale:new Vec3(.25,.25,1)},{easing:'sineOut'}).start();
 }
 tween(cloud).delay(.76).call(()=>{if(cloud.isValid)cloud.destroy();}).start();
}

let white:SpriteFrame|undefined;
function whiteFrame(){
 if(white)return white;
 const texture=new Texture2D();texture.image=new ImageAsset({_data:new Uint8Array([255,255,255,255]),width:1,height:1,format:Texture2D.PixelFormat.RGBA8888,_compressed:false});
 white=new SpriteFrame();white.texture=texture;white.packable=false;return white;
}
/** A real fragment-shader flash and expanding rounded shockwave. */
export class PanelImpact {
 readonly node:Node;
 private material:Material|null=null;
 private flash:Vec4;
 constructor(parent:Node,width:number,height:number,effect?:EffectAsset){
  this.node=new Node('Bonus shader impact');this.node.layer=parent.layer;parent.addChild(this.node);
  const transform=this.node.addComponent(UITransform),w=width+96,h=height+96;transform.setContentSize(w,h);
  this.flash=new Vec4(0,w/h,width/w,height/h);
  if(effect){
   const sprite=this.node.addComponent(Sprite);sprite.sizeMode=Sprite.SizeMode.CUSTOM;sprite.spriteFrame=whiteFrame();transform.setContentSize(w,h);
   const material=this.material=new Material();material.initialize({effectAsset:effect,defines:{USE_TEXTURE:true,USE_LOCAL:false}});sprite.customMaterial=material;material.setProperty('flash',this.flash);
  }
 }
 update(age:number){if(this.material&&this.node.isValid){this.flash.x=Math.min(1,Math.max(0,age/PANEL_IMPACT_SECONDS));this.material.setProperty('flash',this.flash);}}
 destroy(){if(this.node.isValid)this.node.destroy();this.material?.destroy();this.material=null;}
}
