export class CosmicHerdSlot extends ExpansionSlot {
 get bonusSymbol(){return undefined;}
 private cascadeRound(board:string[],bet:number,rng:()=>number,freeLeft?:number){
  const fs=this.tumble(board,bet,rng);let chain=0;
  for(const f of fs){if(f.action==='remove')chain++;f.panel={label:freeLeft===undefined?'CASCADE / FREE':'CASCADE / LEFT',values:[chain,freeLeft??this.freeAward(chain)],columns:2};}
  return {frames:fs,chain};
 }
 private freeAward(chain:number){return chain>=8?50:chain>=7?25:chain>=6?15:chain>=5?10:chain>=4?7:0;}
 play(board:string[],bet:number,rng:()=>number){
  const cascade=this.cascadeRound(board,bet,rng),fs=cascade.frames,count=this.freeAward(cascade.chain),base=this.round(bet,fs);
  if(!count)return this.finish([base]);
  fs.push(this.frame(base.board,'trigger',cascade.chain+'연쇄 · 무료 '+count+'회 확정',[],{panel:{label:'CASCADE / FREE',values:[cascade.chain,count],columns:2}}));
  const rounds=[base];for(let left=count-1;left>=0;left--)rounds.push(this.round(bet,this.cascadeRound(this.draw(bet,rng),bet,rng,left).frames,{freeSpinsRemaining:left}));
  return this.finish(rounds,{freeSpinsAwarded:count,featureOnly:false});
 }
}
