export function joeyUniform(rng:()=>number){const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid Joey uniform');return value;}
export function joeyOrdinary(high:number,rng:()=>number){let value=joeyUniform(rng)*(75+5*high);const weights=[5*high,6,7,8,10,12,14,16,2];for(let i=0;i<9;i++)if((value-=weights[i])<0)return i===8?'wild':String(i);return 'wild';}
