import {ExpansionSlot,ExpansionFrame,Geometry,expansionCells as cells,randomIndex as ri} from './ExpansionCore';
import {PARIS_MODEL,ParisInput,parisOrdinary,parisUniform} from './ParisMath';
export const PARIS_PLACES=['카페','공원','다리','박물관','광장','강변'] as const;
export class PuppyParisSlot extends ExpansionSlot {
 unit(symbol:number,count:number){return (.025+.015*(8-symbol))*Math.pow(2,Math.max(0,count-3));}
 prize(board:string[],bet:number,multiple:number,focus:number[],caption:string,g:Geometry=this.geometry):ExpansionFrame{return this.frame(board,'win',caption,focus,{wins:[{line:-1,symbol:this.id('wild'),cells:[...focus],amount:Math.round(bet*multiple),multiplier:multiple}]},g);}
 private drawWithInput(bet:number,rng:()=>number,input:ParisInput){
  if(!this.bets.includes(bet))throw Error('Invalid bet');const board=Array.from({length:15},()=>this.id(parisOrdinary(bet,rng,input)));for(let col=0;col<5;col++)if(parisUniform(rng)<input.scatterPerReel)board[ri(rng,3)*5+col]=this.id('scatter');return board;
 }
 draw(bet:number,rng:()=>number){return this.drawWithInput(bet,rng,PARIS_MODEL.base);}
 prepareBonusPurchase(_bet:number,_rng:()=>number):never{throw Error('Paris source rewards cannot support100-bet bonus purchase');}
 play(b:string[],bet:number,rng:()=>number){
  const state=this.state(bet,[0]),origin=((state[0]||0)%6+6)%6,markers=cells(b,this.id('scatter'));
  const baseRound=()=>{const r=this.ordinary(b,bet);r.expansionFeature!.frames.forEach(f=>f.route={from:origin,to:origin,position:origin});return r;};
  if(markers.length<3)return this.progressResult(this.finish([baseRound()]),bet,[origin]);
  const destinations=Array.from({length:3},(_,choice)=>(origin+choice+1)%6);
  const branches=destinations.map(destination=>{
   const base=baseRound(),route={from:origin,to:destination,position:origin},arrived={...route,position:destination},free=destination%2===0;
   base.expansionFeature!.frames.push(this.frame(b,'trigger','지도 표식 3개 · 목적지 선택',markers,{route:{from:origin,to:origin,position:origin}}));
   const rounds=[base,this.round(bet,[this.frame(b,'move',PARIS_PLACES[origin]+' → '+PARIS_PLACES[destination],markers,{route}),this.frame(b,'reveal',PARIS_PLACES[destination]+' 보너스 공개',markers,{route:arrived})])];
   if(free){for(let left=3;left>=0;left--){const after=this.drawWithInput(bet,rng,PARIS_MODEL.natural),r=this.ordinary(after,bet,'목적지 무료 회전');r.freeSpinsRemaining=left;r.expansionFeature!.frames.forEach(f=>f.route={...arrived});rounds.push(r);}}
   else rounds.push(this.round(bet,[{...this.prize(b,bet,[1,2,3,5][ri(rng,4)],markers,'장소별 발견 보상'),route:arrived}]));
   return this.progressResult(this.finish(rounds,{featureOnly:!free,...(free?{freeSpinsAwarded:4}:{})}),bet,[destination]);
  });
  return this.choices('지도에서 다음 경로를 선택하세요',destinations.map(d=>PARIS_PLACES[d]+' · '+(d%2===0?'무료 4회':'발견 보상')),branches);
 }
}
