import type {ExpansionFrame} from '../slots/ExpansionCore';
const key=(name:string)=>'ui.thunder.flow.'+name;
/** Read only the currently presented frame; never reveal a future board. */
export function thunderFlow(frame:ExpansionFrame|null,freeRemaining:number|null,busy:boolean){
 const held=frame?.remaining!==undefined,free=freeRemaining!==null;
 const steps=(held?['lock','spin','pay']:['entry','free','result']).map(key);
 let active=-1,status='idle',next='add',remaining=0;
 if(busy&&frame){
  if(held){remaining=frame.remaining!;active=frame.action==='trigger'?0:frame.action==='reels'||frame.action==='effect'?1:2;status='held';next=frame.action==='reels'||frame.action==='effect'?'newHold':remaining>0&&(frame.held?.length??0)<20?'again':free&&(freeRemaining??0)>0?'return':'finish';}
  else if(frame.action==='trigger'){active=0;status='add';next=free?'return':'start';}
  else if(free){active=1;status='freeCount';remaining=freeRemaining;next=remaining>0?'nextFree':'finish';}
 }else if(frame){active=2;status='paid';next='idle';}
 return {steps,active,status:key(status),next:key(next),remaining};
}
