import{gapInputBoard,gapUniform}from'./GapInputBoard';
/** Base law conditioned on SCAT in each of the three central reels. Outer flags remain IID. */
export function compassConditionalBoard(id:string,zero:number,high:number,wild:number,gate:number,rng:()=>number){const board=gapInputBoard(id,5,zero,high,wild,0,rng);for(let c=0;c<5;c++)if(c>=1&&c<=3||gapUniform(rng)<gate)board[Math.floor(gapUniform(rng)*3)*5+c]=id+'-scatter';return board;}
