import {authErrorMessage} from './AuthErrors';
import {scrubError} from './CrashReports';
export function sessionLoadingText(elapsed:number,label='서버 저장 불러오는 중…'){return label.replace(/[.…]+$/,'')+'.'.repeat(Math.floor(Math.max(0,elapsed)/.4)%3+1);}
export function sessionFailure(error:unknown){
 const raw=error as {code?:unknown;message?:unknown};
 const candidate=String(raw?.code||'unknown');
 const code=/^[a-zA-Z0-9/_-]{1,80}$/.test(candidate)?candidate:'unknown';
 const reasons:Record<string,string>={
  'permission-denied':'서버에서 이 계정의 저장 접근을 거부했습니다.',
  unauthenticated:'로그인 인증이 만료되었거나 서버에서 확인되지 않았습니다.',
  unavailable:'저장 서버에 연결하지 못했습니다. 인터넷 연결을 확인해 주세요.',
  'deadline-exceeded':'저장 서버의 응답 시간이 초과되었습니다.',
  'resource-exhausted':'저장 서버의 요청 한도를 초과했습니다. 잠시 후 다시 시도해 주세요.',
  aborted:'다른 저장 요청과 충돌했습니다. 다시 시도해 주세요.',
  conflict:'다른 기기에서 저장이 변경되었습니다. 다시 불러와 주세요.',
 };
 const reason=reasons[code.replace(/^firestore\//,'')]||(code.startsWith('auth/')?authErrorMessage(error):scrubError(raw?.message||'오류의 상세 사유를 확인하지 못했습니다.',220));
 return {code,reason};
}
