import {assetManager,ImageAsset,Rect,resources,Size,SpriteFrame,Texture2D} from 'cc';
import {RUNTIME_ART} from './RuntimeArtManifest';
import {EXPANSION_RUNTIME_ART} from './ExpansionRuntimeArt';
import {SLOT_DECOR_ART} from './SlotDecorManifest';

// Rects in the unmodified ChatGPT download; both wheel pivots are centered.
const SUNSET_WHEEL_ART:Record<string,readonly [string,number,number,number,number]>={
 'sunset-wheel/prize':['sunset-wheel-v1/sheet',168,22,480,480],
 'sunset-wheel/free':['sunset-wheel-v1/sheet',168,502,480,480],
 'sunset-wheel/panel':['sunset-wheel-v1/sheet',823,76,602,872],
};

// Fit the visible Zeus silhouette, excluding the empty upper third of the
// original download. Keep its pixels and texture unchanged.
const SOURCE_ART_CROPS:Record<string,readonly [number,number,number,number]>={
 'slot-art-low-v1/gates-of-clouds/gates-of-clouds-hero-full':[174,357,840,840],
};

// Reuse the approved 32px gold celestial dial for the new Zodiac entry symbol.
// Keep aliases outside the generated manifest so atlas repacking preserves them.
const RULE_SYMBOL_ALIASES:Record<string,string>={
 'slot-art-low-v1/golden-zodiac-choice/golden-zodiac-choice-scatter':'slot-art-low-v1/triple-compass/triple-compass-scatter',
};

// One in-flight load per atlas: startup may request dozens of frames at once.
const textures=new Map<string,Promise<Texture2D>>();
function loadTexture(path:string,sourceAudit:boolean){
 const key=(sourceAudit?'source:':'bundle:')+path;
 let pending=textures.get(key);
 if(!pending){
  pending=new Promise<Texture2D>((resolve,reject)=>{
   const done=(error:Error|null,texture?:Texture2D)=>{if(error||!texture){reject(error||new Error('Missing texture '+path));return;}texture.setFilters(Texture2D.Filter.NEAREST,Texture2D.Filter.NEAREST);resolve(texture);};
   if(sourceAudit){assetManager.loadRemote<ImageAsset>(new URL('/__source_art__/'+path+'.png',location.href).href,{ext:'.png'},(error,asset)=>{if(error){done(error);return;}const texture=new Texture2D();texture.image=asset;done(null,texture);});}
   else resources.load(path+'/texture',Texture2D,done);
  });
  textures.set(key,pending);pending.catch(()=>{textures.delete(key);});
 }
 return pending;
}
export async function loadRuntimeArt(path:string,sourceAudit=false):Promise<SpriteFrame>{
 const packed=RUNTIME_ART[RULE_SYMBOL_ALIASES[path]||path]||EXPANSION_RUNTIME_ART[path]||SUNSET_WHEEL_ART[path]||SLOT_DECOR_ART[path],texture=await loadTexture(packed?.[0]||path,sourceAudit);
 const frame=new SpriteFrame();frame.texture=texture;
 if(packed){frame.rect=new Rect(packed[1],packed[2],packed[3],packed[4]);frame.originalSize=new Size(packed[3],packed[4]);}
 const crop=SOURCE_ART_CROPS[path];
 if(crop){frame.rect=new Rect(frame.rect.x+crop[0],frame.rect.y+crop[1],crop[2],crop[3]);frame.originalSize=new Size(crop[2],crop[3]);}
 return frame;
}
