import type {ExpansionFrame} from '../slots/ExpansionCore';

/** Hold boards use one masked reel per available cell, not full column strips. */
export function isIndependentHoldFrame(frame:ExpansionFrame){
 return frame.action==='reels'&&frame.held!==undefined&&
  (frame.remaining!==undefined||!!frame.dragonVault||!!frame.sumoVault||!!frame.cartBoards);
}
export function independentReelCells(board:string[],held:number[],groups?:ExpansionFrame['cartBoards']){
 const fixed=new Set(held);
 return board.map((_,cell)=>cell).filter(cell=>{
  if(fixed.has(cell))return false;
  if(!groups?.split)return true;
  const panel=Math.floor(cell/30)*2+Math.floor(cell%10/5);
  return groups.active?groups.active.includes(panel):panel<groups.unlocked;
 });
}
