import {NightParkSlot} from './NightParkSlot';
export function nightParkAudit(params:URLSearchParams){
 const slot=new NightParkSlot(),mode=params.get('audit-park'),outcome=params.get('audit-outcome');
 const find=(bet:number,bonus:boolean)=>{let seed=328091;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<100000;i++){const r=slot.spin(bet,rng);if(bonus?r.rounds?.some(r=>mode==='extra'?!!r.freeSpinsAdded:r.parkFeature?.moves.some(m=>m.to===11)):!r.rounds&&(outcome==='no-win'?r.wins.length===0:r.wins.length>1))return r;}throw Error('Park natural audit outcome not found');};
 if(mode==='extra'||mode==='treasure')slot.bonusDemoSpin=bet=>find(bet,true);
 if(outcome==='no-win'||outcome==='multi-win')slot.demoSpin=bet=>find(bet,false);
 return slot;
}
