/** Local, fixed input frequencies. Provider strips and placement probabilities
 * are private. Paytables, power actions, multipliers and spin limits are owned
 * by MoonFeature. These inputs never depend on the wallet or a paid outcome. */
export interface MoonInputProfile {premium:number;bias:number;}
export const MOON_MODEL={
 base:{premium:.35,bias:16},trinity:{premium:.5,bias:1},
 naturalFree:[{premium:.8442909940891479,bias:1},{premium:.8216492270166794,bias:1},{premium:.9975975531904145,bias:1}],
 purchaseFree:[{premium:.5960736807579062,bias:1},{premium:.5830348412542494,bias:1},{premium:.18073895927666603,bias:1}],
};
const pools=new Map<string,{weights:number[];total:number}[]>();
function inputPools(profile:MoonInputProfile){
 const {premium,bias}=profile;if(!Number.isFinite(premium)||premium<0||!Number.isFinite(bias)||bias<=0)throw Error('Invalid Moon fixed inputs');
 const key=premium+':'+bias;let value=pools.get(key);
 if(!value){value=Array.from({length:25},(_,cell)=>{const phase=(cell%5+2*Math.floor(cell/5))%7,weights=[8*premium,8*premium,8*premium,19,19,19,19].map((w,s)=>w*((s===phase||s===(phase+1)%7)?bias:1));return{weights,total:weights.reduce((a,b)=>a+b,0)};});pools.set(key,value);}
 return value;
}
export function moonInputBoard(rng:()=>number,profile:MoonInputProfile){
 return inputPools(profile).map(pool=>{const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid Moon random input');let roll=value*pool.total;for(let s=0;s<7;s++){roll-=pool.weights[s];if(roll<0)return s;}return 6;});
}
export function moonPhaseBoard(rng:()=>number,phase:'base'|'trinity'|'free',guardian:number,purchased=false){
 return moonInputBoard(rng,phase==='free'?(purchased?MOON_MODEL.purchaseFree:MOON_MODEL.naturalFree)[guardian]:MOON_MODEL[phase]);
}
