import {isLobbyReadySlot} from '../slots/PrioritySlots';
export type LobbyFilter='all'|'favorites'|'popular'|'new';
export const NEW_SLOT_PERIOD_MS=30*24*60*60*1000;
export const HOT_CONCURRENT_THRESHOLD=50;
/** Fallback curation for every login, including offline test sessions. */
export const FIRST_LOGIN_CURATED_SLOT_IDS=['gates-of-clouds','book-of-wildead','chaos-crew-x','sugar-lane-rush','le-raccoon-bandit','prairie-buffalo-king'] as const;
export interface LobbyCuration {slotIds:string[];}
export function validateLobbyCuration(value:any):LobbyCuration {
 if(!value||!Array.isArray(value.slotIds)||value.slotIds.length<1||value.slotIds.length>30)throw Error('큐레이션은 출시 슬롯 1–30개를 지정해 주세요.');
 const ids=new Set<string>();
 for(const id of value.slotIds){if(typeof id!=='string'||!isLobbyReadySlot(id)||ids.has(id))throw Error('큐레이션에 중복되거나 미출시된 슬롯이 있습니다.');ids.add(id);}
 return {slotIds:[...value.slotIds]};
}
/** Pin configured visible entries; shuffle only the remainder once per session. */
export function curatedLobbySlots<T extends {id:string}>(items:readonly T[],slotIds:readonly string[]=FIRST_LOGIN_CURATED_SLOT_IDS,rng:()=>number=Math.random):T[]{
 const byId=new Map(items.map(item=>[item.id,item])),ids=Array.from(new Set(slotIds)),featured=ids.flatMap(id=>byId.has(id)?[byId.get(id)!]:[]),selected=new Set(ids);
 return [...featured,...shuffleLobbySlots(items.filter(item=>!selected.has(item.id)),rng)];
}
