export const isNewSlot=(id:string,now=Date.now())=>{const released=Date.parse(slotReleaseDates[id]||'');return Number.isFinite(released)&&now>=released&&now-released<NEW_SLOT_PERIOD_MS;};
export const isHotConcurrent=(count:number|undefined)=>Number.isFinite(count)&&count!>=HOT_CONCURRENT_THRESHOLD;
export const newSlotIds=Object.keys(slotReleaseDates).sort((a,b)=>Date.parse(slotReleaseDates[b])-Date.parse(slotReleaseDates[a]));
export function filterSlots<T extends {id:string}>(items:T[],filter:LobbyFilter,favorites:string[],plays:Record<string,number>={},unlocked:string[]=[],now=Date.now()):T[]{
 if(filter==='favorites')return items.filter(item=>favorites.includes(item.id));
 if(filter==='new')return items.filter(item=>isNewSlot(item.id,now)).sort((a,b)=>Date.parse(slotReleaseDates[b.id])-Date.parse(slotReleaseDates[a.id]));
 if(filter==='popular')return [...items].sort((a,b)=>(plays[b.id]||0)-(plays[a.id]||0));
 return [...items].sort((a,b)=>Number(unlocked.includes(b.id))-Number(unlocked.includes(a.id)));
}
export function sortLobbySlots<T extends {id:string}>(
 items:T[],filter:LobbyFilter,descending:boolean,favorites:string[],plays:Record<string,number>={},managementNumbers:Record<string,number>={},now=Date.now()
):T[]{
 const direction=descending?-1:1;
 const numberOf=(id:string)=>managementNumbers[id]??Number.MAX_SAFE_INTEGER;
 const tieByNumber=(a:T,b:T)=>numberOf(a.id)-numberOf(b.id)||a.id.localeCompare(b.id);
 const favoriteRank=new Map(favorites.map((id,index)=>[id,index]));
 return [...items].sort((a,b)=>{
  let diff=0;
  if(filter==='favorites')diff=(favoriteRank.get(a.id)??Number.MAX_SAFE_INTEGER)-(favoriteRank.get(b.id)??Number.MAX_SAFE_INTEGER);
  else if(filter==='popular')diff=(plays[a.id]||0)-(plays[b.id]||0);
  else if(filter==='new')diff=Date.parse(slotReleaseDates[a.id]||'')-Date.parse(slotReleaseDates[b.id]||'');
  else diff=numberOf(a.id)-numberOf(b.id);
  if(diff!==0)return diff*direction;
  return tieByNumber(a,b)*direction;
 });
}

export function preserveLobbyOrder<T extends {id:string}>(items:T[],previous:string[]|null){
 const ids=new Set(items.map(item=>item.id)),order=(previous||[]).filter(id=>ids.has(id));
 for(const item of items)if(!order.includes(item.id))order.push(item.id);
 const rank=new Map(order.map((id,index)=>[id,index]));
 return{items:[...items].sort((a,b)=>rank.get(a.id)!-rank.get(b.id)!),order};
}

/** Shuffle a copy once per login; callers retain its IDs for the session.
 * A fixed prefix keeps the release lineup's first promoted games in place. */
export function shuffleLobbySlots<T>(items:readonly T[],rng:()=>number=Math.random,fixedCount=0):T[]{
 const fixed=Math.max(0,Math.min(items.length,Math.floor(fixedCount))),shuffled=[...items.slice(fixed)];
 for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]];}
 return [...items.slice(0,fixed),...shuffled];
}

/** Weighted sampling without replacement. Higher weights improve early-list
 * frequency without pinning an item to a particular position. */
export function weightedShuffleLobbySlots<T>(items:readonly T[],weightOf:(item:T)=>number,rng:()=>number=Math.random):T[]{
 const remaining=[...items],result:T[]=[];
 while(remaining.length){
  const weights=remaining.map(item=>Math.max(.001,Number(weightOf(item))||.001)),total=weights.reduce((sum,weight)=>sum+weight,0);
  let roll=Math.max(0,Math.min(.9999999999999999,rng()))*total,index=weights.length-1;
  for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<0){index=i;break;}}
  result.push(remaining.splice(index,1)[0]);
 }
 return result;
}

/** Partition the session shuffle without changing either group's random order. */
export function favoritesFirst<T extends {id:string}>(items:readonly T[],favorites:readonly string[]):T[]{
 const liked=new Set(favorites);
 return [...items.filter(item=>liked.has(item.id)),...items.filter(item=>!liked.has(item.id))];
}
