export function walnutUniform(rng:()=>number){const x=rng();if(!Number.isFinite(x)||x<0||x>=1)throw Error("Invalid walnut uniform");return x;}
export function walnutOrdinary(high:number,rng:()=>number){const w=[4*high,5,6,7,8,12,13,14,15];let roll=walnutUniform(rng)*w.reduce((a,b)=>a+b,0);for(let i=0;i<w.length;i++){roll-=w[i];if(roll<0)return i;}return 8;}
