/** Pass an already localized title. Production builds always retain the plain title. */
export function formatSlotTitle(id:string,localizedTitle:string,development:boolean):string {
 const number=SLOT_MANAGEMENT_NUMBERS[id];
 return development&&number!==undefined?String(number).padStart(2,'0')+' · '+localizedTitle:localizedTitle;
}
