import { SlotMain, SlotConfig, SpinResult, Win, Cascade } from './SlotMain';
/** Independent cluster rules. Fixed paytable calibrated for 400-spin session volatility. */
export class AnimalRush extends SlotMain {
 readonly hasBonus=true;get bonusSymbol(){return 'raccoon';}
 readonly columns=7; readonly rows=7; readonly mode='clusters' as const;
 readonly config: SlotConfig={id:'animal',title:'애니멀 러시',subtitle:'ANIMAL RUSH',tag:'NEW · CLUSTER',color:'#405749',accent:'#f0c69b',description:'귀여운 동물 친구들의 숲속 러시.\n7마리가 모이면 연쇄 행운이 시작돼요.',symbols:[
  {id:'rabbit',name:'토끼',color:'#f4dfd5',weight:22,payout:1},
  {id:'cat',name:'고양이',color:'#e7b581',weight:20,payout:1},
  {id:'dog',name:'강아지',color:'#d8bd91',weight:18,payout:1},
  {id:'fox',name:'여우',color:'#e59a73',weight:12,payout:2},
  {id:'panda',name:'판다',color:'#bbc9b8',weight:10,payout:2},
  {id:'bear',name:'곰',color:'#b99478',weight:8,payout:3},
  {id:'frog',name:'개구리',color:'#97b888',weight:5,payout:4},
  {id:'chick',name:'병아리',color:'#ead287',weight:3,payout:5},
  {id:'raccoon',name:'보너스 너구리',color:'#a8b0bc',weight:1.05029296875,payout:0}
 ]};
 evaluate(board:string[],bet:number):SpinResult{
  if(board.length!==49||!this.bets.includes(bet)||board.some(id=>!this.config.symbols.some(s=>s.id===id)))throw Error('Invalid animal board');
  const visited=new Set<number>(),wins:Win[]=[];
  for(let start=0;start<49;start++){
   if(visited.has(start))continue;const cells:number[]=[],queue=[start],id=board[start];visited.add(start);
   while(queue.length){const at=queue.pop()!;cells.push(at);const neighbors=[...(at>=7?[at-7]:[]),...(at<42?[at+7]:[]),...(at%7>0?[at-1]:[]),...(at%7<6?[at+1]:[])];
    for(const next of neighbors)if(!visited.has(next)&&board[next]===id){visited.add(next);queue.push(next);}
   }
   if(cells.length>=5&&id!=='raccoon'){const symbol=this.config.symbols.find(s=>s.id===id)!;const units=cells.length>=15?109:cells.length>=12?34:cells.length>=9?25:cells.length>=7?7:4;wins.push({line:-1,symbol:id,cells,amount:(bet/5)*symbol.payout*units});}
  }
  return {board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0)};
 }
 spin(bet:number,rng:()=>number=Math.random):SpinResult{
  const base=this.spinRound(bet,rng);let marks=Array<number>(49).fill(0);
  return this.freeSpinSequence(base,()=>{const round=this.spinRound(bet,rng,marks);marks=[...round.cascades![round.cascades!.length-1].nextMultipliers];return round;},round=>{const count=Math.max(...round.cascades!.map(stage=>stage.board.filter(id=>id==='raccoon').length));return count<3?0:[10,12,15,20,30][Math.min(7,count)-3];});
 }
 private spinRound(bet:number,rng:()=>number,initialMarks=Array<number>(49).fill(0)):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  let board=Array.from({length:49},()=>this.pick(rng));const cascades:Cascade[]=[];let payout=0;const wins:Win[]=[];let marks=[...initialMarks];
  for(let step=0;step<8;step++){
   const evaluated=this.evaluate(board,bet);
   const paid=evaluated.wins.map(w=>{const multiplier=Math.max(1,w.cells.reduce((sum,i)=>sum+(marks[i]>=2?marks[i]:0),0));return {...w,multiplier,amount:w.amount*multiplier};});const total=paid.reduce((n,w)=>n+w.amount,0);
   const nextMarks=[...marks];for(const i of new Set(paid.flatMap(w=>w.cells)))nextMarks[i]=marks[i]===0?1:Math.min(128,marks[i]*2);
   const stage:Cascade={board:[...board],wins:paid,payout:total,multiplier:Math.max(1,...paid.map(w=>w.multiplier!)),cellMultipliers:[...marks],nextMultipliers:nextMarks,drops:[]};
   cascades.push(stage);payout+=total;wins.push(...paid);
   if(!paid.length||step===7)break;
   const removed=new Set(paid.flatMap(w=>w.cells));const next=Array<string>(49);
   for(let col=0;col<7;col++){const retained=Array.from({length:7},(_,row)=>row*7+col).filter(i=>!removed.has(i));const incoming=7-retained.length;
    for(let row=0;row<7;row++){const to=row*7+col,from=row<incoming?(row-incoming)*7+col:retained[row-incoming];const symbol=from<0?this.pick(rng):board[from];next[to]=symbol;stage.drops.push({to,from,symbol});}
   }
   board=next;marks=nextMarks;
  }
  return {board:[...board],bet,payout,wins,cascades};
 }
 demoSpin(bet:number):SpinResult{
  const ids=this.config.symbols.map(s=>s.id),initial=Array.from({length:49},(_,i)=>ids[1+i%(ids.length-1)]);for(let i=0;i<7;i++)initial[i]='rabbit';
  const sequence=[...initial,...Array(14).fill('rabbit'),...ids.slice(1,8)];let at=0;
  const total=this.config.symbols.reduce((n,s)=>n+s.weight,0);
  return this.spinRound(bet,()=>{const id=sequence[at++]||'raccoon';let before=0;for(const s of this.config.symbols){if(s.id===id)return (before+s.weight*.5)/total;before+=s.weight;}return .99;});
 }
}

