/** Existing local discovery rules; fixed coin/landing/ordinary inputs only. */
export const RELIC_MODEL:{coin:number;landing:number;highByBet:Record<number,number>}={"coin":0.15639872306820868,"landing":0.17240451226682518,"highByBet":{"20":9.941974922189562,"30":10.278337094151453,"40":10.006291823328297,"50":10.238541239717819,"70":10.152260271940925,"100":10.188652482693524,"150":10.077571746365777,"200":10.11980237965535,"250":10.12266981262744,"300":10.094855958023526,"350":10.101653201258745,"400":10.11980237965535,"450":10.121351318791294,"500":10.105030898196393,"600":10.11980237965535,"700":10.109097101179145,"800":10.11980237965535,"900":10.111318585277651,"1000":10.11980237965535,"2000":10.11980237965535,"3000":10.11980237965535,"4000":10.11980237965535,"5000":10.11980237965535,"6000":10.11980237965535,"7000":10.11980237965535,"8000":10.11980237965535,"9000":10.119802379655347,"10000":10.11980237965535}};
const WEIGHTS=[5,6,7,8,10,12,14,16,2],pools=new Map<number,{high:number;weights:number[];sum:number}>();
export function relicUniform(rng:()=>number){const value=rng();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid Relic random value');return value;}
export function relicCellInput(bet:number,rng:()=>number){
 const u=relicUniform(rng);if(u>=1-RELIC_MODEL.coin)return 'scatter';const high=RELIC_MODEL.highByBet[bet]??1;let pool=pools.get(bet);
 if(!pool||pool.high!==high){const weights=WEIGHTS.map((w,i)=>w*(i===0?high:1));pool={high,weights,sum:weights.reduce((n,w)=>n+w,0)};pools.set(bet,pool);}
 let sample=u/(1-RELIC_MODEL.coin)*pool.sum;for(let i=0;i<9;i++){sample-=pool.weights[i];if(sample<0)return i===8?'wild':i;}return 7;
}
