import {WalnutWorkshopSlot} from './WalnutWorkshopSlot';
export const WALNUT_AUDIT_SEEDS:Record<string,number>={empty:11855961,multi:2711630465,free:503397165,masks:3179376036,ceiling:3016242829};
export function walnutWorkshopAudit(params:URLSearchParams){const s=new WalnutWorkshopSlot(),outcome=params.get('audit-walnut-case')||params.get('audit-outcome')||'',kind=({'no-win':'empty','multi-win':'multi'} as Record<string,string>)[outcome]||outcome,initial=WALNUT_AUDIT_SEEDS[kind];if(initial!==undefined){const spin=(bet:number)=>{let seed=initial;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},r=s.spin(bet,rng);if(['free','masks','ceiling'].includes(kind)){if(r.freeSpinsAwarded!==5||r.rounds?.length!==6)throw Error('Stale Walnut free witness');const rounds=r.rounds.slice(1),steps=rounds.flatMap(q=>q.walnutFeature!.steps);if(kind==='masks'&&new Set(steps.filter(x=>x.kind==='mask').map(x=>x.mask)).size!==5||kind==='ceiling'&&rounds[4].walnutFeature!.after[0]!==10)throw Error('Stale Walnut mask witness');}return r;};s.demoSpin=spin;if(['free','masks','ceiling'].includes(kind))s.bonusDemoSpin=spin;}return s;}
