import {SlotMain,SlotConfig,SpinResult} from './SlotMain';
import {BET_LEVELS} from './BetLevels';
import {QUICK_SYMBOLS,quickSymbol as s,quickFreeSequence,quickChipRound,QuickPackage,QuickTurn} from './QuickFeature';
export class QuickPreviewSlot extends SlotMain {
 constructor(private readonly fixture='pick'){super();}
 readonly columns=5;readonly rows=3;readonly mode='lines' as const;readonly paylines:number[][]=[];readonly bets=[...BET_LEVELS];
 readonly config:SlotConfig={id:'huuuge-jackpot-club',title:'클로버 퀵윈',subtitle:'CLOVER QUICK WIN',tag:'무료 피처 초안',color:'#352640',accent:'#b9d775',description:'보너스 3개 · 클로버 선택 판\n같은 횟수·배수 세 장 일치\n일치한 무료 횟수와 배수 확정\n무료 당첨에 선택 배수 적용\n칩 개수별 잭팟은 후속 구현',symbols:QUICK_SYMBOLS.map((name,i)=>({id:s(name),name:['체리','종','7','겹7','BAR','WILD','BONUS','퀵 칩'][i],color:'#b9d775',weight:0,payout:0}))};
 artResource(id:string){if(!this.config.symbols.some(symbol=>symbol.id===id))throw Error('Unknown Quick art');return 'slot-art-handcrafted-v1/huuuge-jackpot-club/'+id.slice('huuuge-jackpot-club-'.length);}
 spin():SpinResult{throw Error('Quick draft is free playback only');}
 demoSpin(bet:number):SpinResult{
  if(!this.bets.includes(bet))throw Error('Invalid bet');const blank=()=>Array.from({length:15},(_,cell)=>s(QUICK_SYMBOLS[cell%5])),trigger=blank();if(this.fixture==='no-win')return {bet,board:trigger,wins:[],payout:0};
  if(/^chips-[4-9]$/.test(this.fixture)){
   const count=Number(this.fixture.slice(-1));for(let cell=0;cell<count;cell++)trigger[cell]=s('quick-chip');
   [10,11,12].forEach(cell=>trigger[cell]=s('bell'));
   // Isolated presentation fixture amounts only. No provider payout table is inferred.
   return quickChipRound(trigger,bet,[{line:0,symbol:s('bell'),cells:[10,11,12],amount:bet}],{awardsByCount:{5:13,6:29,7:47,8:71,9:101},phase:'base',packageMultiplierPolicy:{kind:'excluded'}});
  }
  [5,2,8].forEach(cell=>trigger[cell]=s('bonus'));
  const deck:QuickPackage[]=Array.from({length:20},(_,cell)=>cell%3===0?{spins:20,multiplier:3}:cell%3===1?{spins:15,multiplier:2}:{spins:7,multiplier:2});
  const order=[0,2,1,5,8],turns:QuickTurn[]=Array.from({length:7},(_,n)=>{const board=blank();board[5]=board[6]=board[7]=s('bell');return {board,wins:n%3===0?[{line:0,symbol:s('bell'),amount:bet,cells:[5,6,7]}]:[]};});
  const triggerWins=this.fixture==='pick-with-line'?[{line:0,symbol:s('bell'),amount:bet,cells:[10,11,12]}]:[];
  if(triggerWins.length)[10,11,12].forEach(cell=>trigger[cell]=s('bell'));
  return quickFreeSequence(trigger,deck,order,turns,bet,triggerWins);
 }
}
