import {DigitPreviewSlot} from './DigitPreviewSlot';
import {DIGIT_DECOR,DIGIT_NUMBERS,digitResult,digitSymbol,DigitBoost} from './DigitFeature';
import {SlotConfig,Win} from './SlotMain';
/** Playable local rules candidate. Concatenation and boost follow the observed
 * game; the ordinary pays and distributions below are explicit local choices,
 * not a recovered provider paytable. Remains outside the lobby pending review. */
export class DigitSlot extends DigitPreviewSlot {
 // Operational flag: bypass legacy social-slot payout scaling for the exact
 // numeric formula. It does not certify the local ordinary table below.
 readonly usesReferencePayouts=true;
 readonly maxWin=100000000;
 readonly config:SlotConfig={...this.baseConfig(),tag:'숫자 연결 · 한 칸 상승'};
 private baseConfig():SlotConfig{return new DigitPreviewSlot().config;}
 readonly ordinaryPays={bar:[1,3,8],'double-bar':[2,6,16],'triple-bar':[3,9,24],chip:[1,4,10],dice:[2,5,15]};
 private draw(rng:()=>number):number|string{
  if(rng()<.18){const numbers=rng()<.015?DIGIT_NUMBERS.filter(n=>n>9):DIGIT_NUMBERS.filter(n=>n<10);return numbers[Math.floor(rng()*numbers.length)];}
  return DIGIT_DECOR[Math.floor(rng()*DIGIT_DECOR.length)];
 }
 resolve(landed:(number|string)[],bet:number,boost?:DigitBoost){
  if(!this.bets.includes(bet))throw Error('Invalid Digit bet');
  const groups:number[][]=[];let group:number[]=[];
  for(let cell=0;cell<=landed.length;cell++){
   if(typeof landed[cell]==='number')group.push(cell);
   else{if(group.length>=2)groups.push(group);group=[];}
  }
  const ordinary:Win[]=[];
  if(typeof landed[0]==='string'){
   const value=landed[0] as keyof typeof this.ordinaryPays;let count=1;
   while(count<5&&landed[count]===value)count++;
   if(count>=3&&this.ordinaryPays[value])ordinary.push({line:0,symbol:digitSymbol(value),amount:bet*this.ordinaryPays[value][count-3],cells:Array.from({length:count},(_,i)=>i)});
  }
  return digitResult(landed,groups,bet,boost,ordinary);
 }
 spin(bet:number,rng:()=>number=Math.random){
  if(!this.bets.includes(bet))throw Error('Invalid Digit bet');
  const landed=Array.from({length:5},()=>this.draw(rng));let boost:DigitBoost|undefined;
  const eligible=landed.flatMap((value,cell)=>typeof value==='number'&&value<99&&(typeof landed[cell-1]==='number'||typeof landed[cell+1]==='number')?[cell]:[]);
  if(eligible.length&&rng()<.04){const cell=eligible[Math.floor(rng()*eligible.length)],before=landed[cell] as number,larger=DIGIT_NUMBERS.filter(value=>value>before);boost={cell,before,after:larger[Math.floor(rng()*larger.length)]};}
  return this.resolve(landed,bet,boost);
 }
 demoSpin(bet:number){return this.spin(bet);}
 evaluate(board:string[],bet:number){return this.resolve(board.map(id=>{const value=id.slice('double-lucky-'.length);if(!id.startsWith('double-lucky-'))throw Error('Invalid Digit symbol');return /^\d+$/.test(value)?Number(value):value;}),bet);}
}
