export const TRANSITION_OBJECTS = [
 'gem', 'chest', 'cane', 'castle', 'moon', 'tent',
 'arcade', 'coins', 'star', 'candy', 'lantern', 'marquee',
] as const;

export const TRANSITION_THEMES = [
 {id:'treasure', sky:'#171b39', floor:'#27304c', accent:'#55bfc3', objects:['gem','chest','coins','star']},
 {id:'candy', sky:'#352244', floor:'#5b3152', accent:'#d58bb4', objects:['cane','castle','candy','star']},
 {id:'moonlight', sky:'#151733', floor:'#282342', accent:'#7d9c9c', objects:['moon','tent','lantern','star']},
 {id:'arcade', sky:'#21182e', floor:'#3b2547', accent:'#8a72ad', objects:['arcade','marquee','coins','gem']},
] as const;

/** One advance per real entry/exit, independent of render and gameplay RNG. */
export class TransitionSceneryCycle {
 private cursors={entry:-1,exit:1};
 private previous=-1;
 next(entering=true){
  const key=entering?'entry':'exit';
  let value=(this.cursors[key]+1)%TRANSITION_THEMES.length;
  if(value===this.previous)value=(value+1)%TRANSITION_THEMES.length;
  this.cursors[key]=value;this.previous=value;return value;
 }
}

export function transitionDecorLayout(w:number,h:number,variant:number){
 const theme=TRANSITION_THEMES[variant%TRANSITION_THEMES.length];
 const big=Math.min(144,w*.22),small=big*.58;
 return {
  theme,
  objects:[
   {id:theme.objects[0],x:w*.10,y:h*.09,size:small},
   {id:theme.objects[3],x:w*.76,y:h*.12,size:small*.70},
   {id:theme.objects[1],x:w*.10,y:h*.81,size:big},
   {id:theme.objects[2],x:w*.71,y:h*.84,size:big},
   {id:theme.objects[0],x:w*.45,y:h*.90,size:small*.7},
  ],
 };
}

export function bookRevealLayout(contentWidth:number,viewportHeight:number){
 const width=Math.min(560,contentWidth-64),height=width*.75;
 return {width,height,x:(contentWidth-width)/2,y:(viewportHeight-height)/2,
  titleY:height*.30,nameY:height*.68,iconY:height*.53,iconSize:width*.16};
}
