import {Color,Graphics,Node,Sprite,SpriteFrame,UIOpacity,UITransform,Vec3,tween} from 'cc';
import {transitionDecorLayout} from './SlotDecorLayout';

function sprite(parent:Node,name:string,frame:SpriteFrame,x:number,y:number,w:number,h:number){
 const node=new Node(name);node.layer=parent.layer;parent.addChild(node);
 const transform=node.addComponent(UITransform);transform.setAnchorPoint(0,1);transform.setContentSize(w,h);node.setPosition(x,-y);
 const image=node.addComponent(Sprite);image.sizeMode=Sprite.SizeMode.CUSTOM;image.spriteFrame=frame;
 return node;
}
function rect(g:Graphics,x:number,y:number,w:number,h:number,color:string){g.fillColor=new Color(color);g.rect(x,-y-h,w,h);g.fill();}

export function drawBookRevealDecor(parent:Node,frame:SpriteFrame|undefined,w:number,h:number){
 if(frame)sprite(parent,'Book scarab and column frame',frame,0,0,w,h);
}

export function drawTransitionDecor(parent:Node,frames:ReadonlyMap<string,SpriteFrame>,w:number,h:number,variant:number){
 const layout=transitionDecorLayout(w,h,variant),g=parent.addComponent(Graphics);
 parent.name='Transition scenery '+layout.theme.id;
 rect(g,0,0,w,h,layout.theme.sky);
 // Simple low-resolution scenic layers have no additional bitmap cost.
 const step=16,horizon=Math.round(h*.79/step)*step;
 for(let x=0;x<w;x+=step*3){const height=step*(2+(Math.floor(x/48)+variant)%4);rect(g,x,horizon-height,48,height,layout.theme.floor);}
 rect(g,0,horizon,w,h-horizon,layout.theme.floor);
 for(let i=0;i<14;i++){const x=32+(i*149)%(w-64),y=40+(i*113)%(h*.21);rect(g,x,y,4,4,layout.theme.accent);}
 for(const [index,object]of layout.objects.entries()){
  const frame=frames.get('transition-decor/'+object.id);if(!frame)continue;
  const node=sprite(parent,'Transition '+layout.theme.id+' '+object.id,frame,object.x,object.y,object.size,object.size);
  const opacity=node.addComponent(UIOpacity);opacity.opacity=index<2?180:235;
  tween(node).delay(index*.10).by(1.9,{position:new Vec3(0,3,0)},{easing:'sineInOut'}).by(1.9,{position:new Vec3(0,-3,0)},{easing:'sineInOut'}).union().repeatForever().start();
 }
}
