export function bridgeUniform(rng:()=>number){const u=rng();if(!Number.isFinite(u)||u<0||u>=1)throw Error("Invalid Bridge uniform");return u;}
export function bridgeOrdinary(h:number,rng:()=>number){const w=[5*h,6,7,8,10,12,14,16];let u=bridgeUniform(rng)*w.reduce((a,b)=>a+b,0);for(let k=0;k<8;k++){u-=w[k];if(u<0)return String(k);}return "7";}
