import {MoonResolvedRound,MoonStage,MoonPower} from './MoonFeature';
import type {SpinResult,Win} from './SlotMain';

export interface MoonPlaybackStage extends MoonStage {wins:Win[];}
export interface MoonPlayback {
 mode:'base'|'trinity'|'free';guardian:MoonPower;stages:MoonPlaybackStage[];
 cleared:boolean;multiplier:number;meter:number;clearAward?:Win;
}
export const moonSymbol=(id:string,symbol:number)=>id+'-'+(symbol<0?'void':symbol===7?'wild':symbol===8?'mixed':symbol);

/** Presentation records share the exact winning entries used by settlement,
 * including source multipliers, powers, drops and full-clear awards. */
export function moonResult(id:string,bet:number,round:MoonResolvedRound):SpinResult{
 const stages=round.stages.map(stage=>({...stage,wins:stage.runs.map((run,index):Win=>({
  line:-1,symbol:moonSymbol(id,run.symbol),cells:[...run.cells],amount:stage.awards[index],multiplier:stage.multiplierBefore,
 }))}));
 const clearAward:Win|undefined=round.clearAward?{line:-1,symbol:id+'-wild',cells:[],amount:round.clearAward,multiplier:100}:undefined;
 const wins=[...stages.flatMap(stage=>stage.wins),...(clearAward?[clearAward]:[])];
 if(wins.reduce((sum,win)=>sum+win.amount,0)!==round.payout)throw Error('Moon presentation payout mismatch');
 return{bet,openingBoard:round.opening.map(symbol=>moonSymbol(id,symbol)),board:round.board.map(symbol=>moonSymbol(id,symbol)),wins,payout:round.payout,
  freeSpinsAdded:round.freeSpinsAdded,freeSpinsRemaining:round.mode==='free'?round.freeSpinsRemaining:undefined,
  moonFeature:{mode:round.mode,guardian:round.guardian,stages,cleared:round.cleared,multiplier:round.multiplier,meter:round.meter,clearAward},
  roundLabel:round.mode==='trinity'?'TRINITY · 세 수호자의 힘':round.mode==='free'?'FREE SPINS · 남은 '+round.freeSpinsRemaining+'회':undefined,
 };
}
