import {Cascade,SpinResult,Win} from './SlotMain';

export interface SweetContext {
 id:string;bet:number;free:boolean;limit:number;
 settle?:(amount:number)=>number;
 pick:()=>string;multiplier:()=>number;pay:(symbol:number,count:number)=>number;
}
/** Candy bombs exist only in free games, remain through one tumble and never carry a bank into the next spin. */
export function sweetRound(context:SweetContext,opening?:string[]):SpinResult{
 const {id,bet,pick,pay,free,limit}=context,orb=id+'-wild',scatter=id+'-scatter';
 let board=opening?[...opening]:Array.from({length:30},pick);
 if(!free&&board.includes(orb))throw Error('Candy bombs cannot appear in the base game');
 let values=board.map(symbol=>symbol===orb?context.multiplier():0);
 const stages:Cascade[]=[],wins:Win[]=[];
 const symbolIndex=new Map(Array.from({length:9},(_,n)=>[id+'-'+n,n] as const));
 let subtotal=0;
 // A deterministic broken RNG must fail before consuming a bet, never hang the UI.
 for(let step=0;step<1024;step++){
  const stageWins:Win[]=[],groups:number[][]=Array.from({length:9},()=>[]);
  for(let cell=0;cell<board.length;cell++){const symbol=symbolIndex.get(board[cell]);if(symbol!==undefined)groups[symbol].push(cell);}
  for(let symbol=0;symbol<9;symbol++){
   const cells=groups[symbol];
   if(cells.length>=8){const amount=Math.min(Math.max(0,limit-subtotal),(context.settle||Math.round)(bet*pay(symbol,cells.length)));if(amount){stageWins.push({line:-1,symbol:id+'-'+symbol,cells,amount});subtotal+=amount;}}
  }
  const removed=new Set(stageWins.flatMap(win=>win.cells));
  const stage:Cascade={board:[...board],wins:stageWins,payout:stageWins.reduce((n,w)=>n+w.amount,0),multiplier:1,cellMultipliers:Array(30).fill(0),nextMultipliers:Array(30).fill(0),symbolValues:[...values],drops:[],removedCells:[...Array.from(removed)]};
  stages.push(stage);wins.push(...stageWins);
  if(!removed.size||subtotal>=limit)break;
  const next=Array<string>(30),nextValues=Array<number>(30).fill(0);
  for(let col=0;col<6;col++){
   const kept=Array.from({length:5},(_,row)=>row*6+col).filter(cell=>!removed.has(cell)),incoming=5-kept.length;
   for(let row=0;row<5;row++){
    const to=row*6+col,from=row<incoming?-1:kept[row-incoming],symbol=from<0?pick():board[from];
    next[to]=symbol;nextValues[to]=from<0?(symbol===orb?context.multiplier():0):values[from];
    stage.drops.push({from:from<0?(row-incoming)*6+col:from,to,symbol});
   }
  }
  board=next;values=nextValues;
  if(step===1023)throw Error('Sweet tumble did not converge');
 }
 let total=0;
 const orbs=free&&subtotal>0?board.flatMap((symbol,cell)=>symbol===orb?[{cell,value:values[cell],total:0}]:[]).sort((a,b)=>b.value-a.value||a.cell-b.cell).map(item=>({...item,total:total+=item.value})):[];
 const applied=orbs.length?Math.max(1,total):1;
 const extra=Math.min(Math.max(0,limit-subtotal),Math.round(subtotal*(applied-1)));
 const adjustment=extra>0?{line:-1,symbol:orb,cells:orbs.map(item=>item.cell),amount:extra,multiplier:applied,caption:'캔디 폭탄 합산 ×'+applied}:undefined;
 if(adjustment)wins.push(adjustment);
 const scatterCells=board.flatMap((symbol,cell)=>symbol===scatter?[cell]:[]),scatterPay=scatterCells.length>=6?100:scatterCells.length===5?5:scatterCells.length===4?3:0;
 const scatterAmount=Math.min(Math.max(0,limit-subtotal-extra),bet*scatterPay);
 const scatterAward=scatterAmount?{line:-1,symbol:scatter,cells:scatterCells,amount:scatterAmount}:undefined;
 if(scatterAward)wins.push(scatterAward);
 return{board,bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),cascades:stages,symbolValues:values,adjustment,scatterAward,
  multiplierCollection:{kind:'candy-bombs',before:0,after:total,subtotal,applied,orbs}};
}
