import {ToyDefendersSlot} from './ToyDefendersSlot';
export function toyDefendersAudit(params:URLSearchParams){
 const slot=new ToyDefendersSlot(),outcome=params.get('audit-outcome'),mode=params.get('audit-toy')||outcome,choice=Math.max(0,Math.min(2,Number(params.get('audit-choice'))||0));
 const find=(bet:number,bonus:boolean)=>{let seed=339281;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<100000;i++){const r=slot.spin(bet,rng);if(bonus){const rounds=r.featureChoices?.results[choice].rounds;if(rounds?.[rounds.length-1]?.toyFeature?.status===(mode==='clear'?'cleared':'overrun'))return r;}else if(!r.rounds&&(outcome==='no-win'?r.wins.length===0:outcome==='single-win'?r.wins.length===1:r.wins.length>1))return r;}throw Error('Defense natural outcome unavailable');};
 if(['no-win','single-win','multi-win'].includes(outcome||''))slot.demoSpin=bet=>find(bet,false);
 if(mode==='clear'||mode==='overrun')slot.bonusDemoSpin=bet=>find(bet,true);
 return slot;
}
