import {SlotMain,SlotConfig,SpinResult,Win} from './SlotMain';import {BET_LEVELS} from './BetLevels';import {WOLF_LINES} from './WolfRules';import {SlotProgress,normalizeSlotProgress,socialPresentation} from './Social2230Rules';
export const BELL_ID='tenth-bell-sheriff';
const extra=Array.from({length:243},(_,i)=>{let code=i;return Array.from({length:5},(_,col)=>{const row=code%3;code=Math.floor(code/3);return row*5+col;});}).filter(line=>!WOLF_LINES.some(other=>other.every((c,i)=>c===line[i])));
export const BELL_LINES=[...WOLF_LINES,...extra.slice(0,25)];
export const BELL_PAYS=[[1.2,3.2,8],[1,2.4,6],[.8,2,4.8],[.6,1.6,4],[.4,1.2,3.2],[.4,1,2.4],[.4,.8,2]];
export interface BellPlayback {cycleBefore:number;cycleAfter:number;before:string[];after:string[];columns:number[];wins:Win[];}
export class TenthBellSlot extends SlotMain {
 readonly columns=5;readonly rows=3;readonly paylines=BELL_LINES;readonly bets=[...BET_LEVELS];readonly usesLocalPayouts=true;readonly maxWin=10000;private progress:SlotProgress={};setProgress(value:SlotProgress){this.progress=normalizeSlotProgress(value);}
 readonly presentation=socialPresentation('열 번째 회전 · 배지 두 개의 릴 전체 WILD','열 번째 종');
 readonly config:SlotConfig={id:BELL_ID,title:'열 번째 종의 보안관',subtitle:'TENTH BELL SHERIFF',tag:'EVERY TENTH SPIN',color:'#443728',accent:'#e1bc76',description:'5×3 · 50라인 · 왼쪽부터3개 이상\n열 번째 유료 회전에만 배지2개 이상이 있는 릴 전체가 WILD로 변합니다.\n변환이 모두 끝난 판에서 한 번만 지급합니다.\n다른 회전에서는 배지가 쌓여도 변환하지 않습니다.\n회전 주기는 베팅별 저장. 별도 프리스핀 없음.',symbols:['카우보이 모자','붉은 목도리','사무소 열쇠','가죽 안장','황동 박차','수배 두루마리','금색 편자','보안관 배지','황금 종 WILD','회중시계'].map((name,i)=>({id:BELL_ID+'-'+(i===8?'wild':i===9?'scatter':i),name,color:'#e1bc76',weight:[5,6,8,10,12,14,16,6,2,2][i],payout:i<7?BELL_PAYS[i][2]:0}))};
 evaluate(board:string[],bet:number):SpinResult {if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!this.config.symbols.some(t=>s===t.id)))throw Error('Invalid bell spin');const wins:Win[]=[];this.paylines.forEach((line,index)=>{let best:Win|undefined;for(let s=0;s<7;s++){const cells:number[]=[];for(const c of line){if(board[c]!==BELL_ID+'-'+s&&board[c]!==BELL_ID+'-wild')break;cells.push(c);}if(cells.length<3)continue;const amount=Math.round(bet*BELL_PAYS[s][cells.length-3]);if(!best||best.amount<amount)best={line:index,symbol:BELL_ID+'-'+s,cells,amount};}if(best)wins.push(best);});return{board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};}
 resolve(before:string[],bet:number):SpinResult {
  this.evaluate(before,bet);const cycleBefore=this.progress[BELL_ID+':'+bet]?.[0]||0,cycleAfter=(cycleBefore+1)%10,columns=cycleBefore===9?[0,1,2,3,4].filter(col=>[col,col+5,col+10].filter(c=>before[c]===BELL_ID+'-7').length>=2):[],after=[...before];for(const col of columns)for(const cell of [col,col+5,col+10])after[cell]=BELL_ID+'-wild';const r=this.evaluate(after,bet);r.bellFeature={cycleBefore,cycleAfter,before:[...before],after:[...after],columns,wins:r.wins};r.progressUpdate={key:BELL_ID+':'+bet,values:[cycleAfter]};return r;
 }
 spin(bet:number,rng:()=>number=Math.random){if(!this.bets.includes(bet))throw Error('Invalid bet');return this.resolve(Array.from({length:15},()=>this.pick(rng)),bet);}
 demoSpin(bet:number){let seed=370928;const rng=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<10000;i++){const r=this.spin(bet,rng);if(r.payout)return r;}throw Error('Bell fixture unavailable');}
}
