import {BET_LEVELS} from './BetLevels';
import {SlotMain,SlotConfig,SpinResult,Win,SlotPresentation} from './SlotMain';
import {WOLF_LINES} from './WolfRules';
import{gapInputBoard}from'./GapInputBoard';
import{compassConditionalBoard}from'./CompassInputBoard';
import{COMPASS_MODEL}from'./TripleCompassMath';
import {drawCompass,compassReward,CompassPlayback} from './CompassFeature';

export const COMPASS_ID='triple-compass';
export const COMPASS_PAYS=[[1.2,3.2,8],[1,2.4,6],[.8,2,4.8],[.6,1.6,4],[.4,1.2,3.2],[.4,1,2.4],[.4,.8,2],[.4,.8,1.6]];
export interface CompassRound extends SpinResult {compassFeature?:CompassPlayback;compassTransform?:{before:string[];cells:number[]};}
/** Independent draft. Wheel flow is inspired by Wizards of Fortune (2019).
 * Fixed 25 lines, distributions, wheel awards, and finite bonus durations are local design.
 * The source's persistent map is not implemented; do not claim source-complete status. */
export class TripleCompassSlot extends SlotMain {
 readonly bonusCalibrationKey=COMPASS_ID+':branching-v1';readonly usesLocalPayouts=true;readonly columns=5;readonly rows=3;readonly paylines=WOLF_LINES;readonly bets=[...BET_LEVELS];readonly hasBonus=true;readonly maxWin=10000;
 get bonusSymbol(){return COMPASS_ID+'-scatter';}
 readonly presentation:SlotPresentation={evidence:'source-title-pending',anticipationText:'중앙 세 릴의 나침반을 기다립니다',triggerText:'삼중 나침반 활성화',bonusInText:'주 나침반 → 수량 → 보조 나침반',hitText:'항해 보상',totalWinText:'항해 총 보상',signature:'부모 휠이 다음 휠을 지정',uiEffect:'휠 순차 정지',soundCue:'featureLand',anticipationHold:.3,hitHold:.25,outHold:.4};
 readonly config:SlotConfig={id:COMPASS_ID,title:'삼중 나침반 마법소',subtitle:'TRIPLE COMPASS',tag:'BRANCHING WHEELS',color:'#26394c',accent:'#a0dbce',description:'5×3 · 25라인 · 왼쪽부터 3개 이상\n2·3·4릴에 나침반이 각각 나오면 휠 보너스\n주 휠이 효과를 고르고 수량 휠이 2~5를 정합니다.\n강화·보물 결과만 보조 보상 휠로 이어집니다.',symbols:['망원경','항해도','육분의','마법 잉크','방위 자석','선박종','로프','돛','항로 WILD','나침반'].map((name,n)=>({id:COMPASS_ID+'-'+(n===8?'wild':n===9?'scatter':n),name,color:'#a0dbce',weight:[5,6,7,8,10,12,14,16,3,8.5][n],payout:n<8?COMPASS_PAYS[n][2]:0}))};
 private validate(board:string[],bet:number){if(!this.bets.includes(bet)||board.length!==15||board.some(s=>!this.config.symbols.some(t=>t.id===s)))throw Error('Invalid compass spin');}
 evaluate(board:string[],bet:number):CompassRound {
  this.validate(board,bet);const wins:Win[]=[];
  this.paylines.forEach((line,index)=>{
   let best:Win|undefined;
   for(let s=0;s<8;s++){
    const cells:number[]=[];for(const cell of line){if(board[cell]!==COMPASS_ID+'-'+s&&board[cell]!==COMPASS_ID+'-wild')break;cells.push(cell);}
    if(cells.length<3)continue;const amount=Math.round(bet*COMPASS_PAYS[s][cells.length-3]);
    if(!best||amount>best.amount)best={line:index,symbol:COMPASS_ID+'-'+s,cells,amount};
   }
   if(best)wins.push(best);
  });return {board:[...board],bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),presentation:this.presentation};
 }
 private draw(bet:number,rng:()=>number,free=false){if(!this.bets.includes(bet))throw Error('Invalid Compass bet');const M=COMPASS_MODEL;return this.evaluate(gapInputBoard(COMPASS_ID,5,free?M.freeZero:M.baseZero,free?1:M.highByBet[bet as keyof typeof M.highByBet],M.restWild,free?0:M.scatterGate,rng),bet);}
 triggerCells(board:string[]){return [1,2,3].flatMap(col=>{const c=[col,col+5,col+10].find(c=>board[c]===this.bonusSymbol);return c===undefined?[]:[c];});}
 private settle(rounds:CompassRound[]):SpinResult {
  const bet=rounds[0].bet;let left=bet*this.maxWin;
  for(const round of rounds){for(const win of round.wins){win.amount=Math.min(left,win.amount);left-=win.amount;}round.payout=round.wins.reduce((n,w)=>n+w.amount,0);}
  return {board:[...rounds[rounds.length-1].board],bet,wins:rounds.flatMap(r=>r.wins),payout:rounds.reduce((n,r)=>n+r.payout,0),rounds,presentation:this.presentation,featureName:'나침반 항해',bonusEndReason:left?'spins-exhausted':'max-win'};
 }
 private bonus(base:CompassRound,rng:()=>number):SpinResult {
  const feature=drawCompass(this.triggerCells(base.board),rng),q=feature.quantity;
  const gate:CompassRound={board:[...base.board],bet:base.bet,wins:[],payout:0,compassFeature:feature,presentation:this.presentation};
  const rounds:CompassRound[]=[base,gate];
  const award=(multiple:number)=>{const win:Win={line:-1,symbol:this.bonusSymbol,cells:[...feature.sourceCells],amount:Math.round(base.bet*multiple)};gate.wins.push(win);feature.awards.push(win);gate.payout+=win.amount;};
  if(feature.mode==='free')for(let i=0;i<q;i++){const r=this.draw(base.bet,rng,true);r.roundLabel='항해 '+(i+1)+' / '+q;rounds.push(r);}
  if(feature.mode==='wild'){
   const board=[...base.board],available=board.flatMap((s,c)=>s!==this.bonusSymbol&&s!==COMPASS_ID+'-wild'?[c]:[]);
   for(let i=0;i<q&&available.length;i++){const index=Math.floor(rng()*available.length),cell=available.splice(index,1)[0];board[cell]=COMPASS_ID+'-wild';feature.transformedCells.push(cell);}
   const result=this.evaluate(board,base.bet);result.openingBoard=[...base.board];result.compassTransform={before:[...base.board],cells:[...feature.transformedCells]};rounds.push(result);
  }
  if(feature.mode==='repeat'){
   // Replay the source hit as separately paid repetitions, never replay its trigger.
   for(let i=1;i<q;i++){
    const wins=base.wins.map(w=>({...w,cells:[...w.cells]}));
    rounds.push({board:[...base.board],bet:base.bet,wins,payout:wins.reduce((n,w)=>n+w.amount,0),roundLabel:'반복 보상 '+i+' / '+(q-1),presentation:this.presentation});
   }
  }
  if(feature.mode==='multiply'){
   // The original base pays once; only the extra q-1 part belongs to this step.
   for(const w of base.wins){const copy={...w,cells:[...w.cells],amount:w.amount*(q-1)};gate.wins.push(copy);feature.awards.push(copy);gate.payout+=copy.amount;}
  }
  if(feature.mode==='upgrade'||feature.mode==='prize')award(compassReward(feature));
  if(feature.mode==='pick'){
   // Choose between fixed safe and variable explorer rewards before presentation.
   const risk=[0,0,1,3][Math.floor(rng()*4)]*q;
   const make=(multiple:number)=>{const win:Win={line:-1,symbol:this.bonusSymbol,cells:[...feature.sourceCells],amount:Math.round(base.bet*multiple)};
    const branchGate:CompassRound={...gate,board:[...gate.board],wins:[],payout:0,compassFeature:{...feature,awards:[]}};const reward:CompassRound={board:[...gate.board],bet:base.bet,wins:[win],payout:win.amount,roundLabel:'선택 항로 보상'};
    const branchBase={...base,board:[...base.board],wins:base.wins.map(w=>({...w,cells:[...w.cells]}))};return this.settle([branchBase,branchGate,reward]);};
   const results=[make(q),make(risk)],selected=results[0];
   return {...selected,featureChoices:{title:'항해 보상 선택',labels:['안전 항로 · '+q+'배','탐험 항로 · 0~'+q*3+'배'],defaultIndex:0,results}};
  }
  return this.settle(rounds);
 }
 spin(bet:number,rng:()=>number=Math.random):SpinResult {const base=this.draw(bet,rng);return this.triggerCells(base.board).length===3?this.bonus(base,rng):base;}
 prepareBonusPurchase(bet:number,rng:()=>number):SpinResult {
  if(!this.bets.includes(bet))throw Error('Invalid Compass bet');const M=COMPASS_MODEL,base=this.evaluate(compassConditionalBoard(COMPASS_ID,M.baseZero,M.highByBet[bet as keyof typeof M.highByBet],M.restWild,M.scatterGate,rng),bet);
  const natural=this.bonus(this.evaluate(base.board,bet),rng);
  const extract=(source:SpinResult):SpinResult=>{
   const rounds=source.rounds!.slice(1),wins=rounds.flatMap(r=>r.wins);
   return {...source,rounds,wins,payout:wins.reduce((n,w)=>n+w.amount,0),bonusTriggerRound:{board:[...base.board],bet,wins:[],payout:0,presentation:this.presentation}};
  };
  if(natural.featureChoices){const choice=natural.featureChoices,results=choice.results.map(extract);return {...results[choice.defaultIndex],featureChoices:{...choice,results}};}
  return extract(natural);
 }
 demoSpin(bet:number){const board=Array.from({length:15},(_,i)=>COMPASS_ID+'-'+i%8);for(const c of [5,6,7])board[c]=COMPASS_ID+'-0';return this.evaluate(board,bet);}
 bonusDemoSpin(bet:number):SpinResult {const board=Array.from({length:15},(_,i)=>COMPASS_ID+'-'+i%8);for(const c of [1,7,13])board[c]=this.bonusSymbol;const r=this.evaluate(board,bet);let index=0;return this.bonus(r,()=>[.8,.55,.7][index++%3]);}
}
