import {DAILY_FREE_COINS,REWARDED_AD_COINS} from './EconomyBalance';
export type RewardCurrency='coins'|'tickets';
export interface AdQuota {remaining:number;readyAt:number;}
export interface RewardState {lastSeen:number;daily:Record<RewardCurrency,string>;ads:Record<RewardCurrency,AdQuota>;adDays:Record<RewardCurrency,{day:string;used:number}>;}
export const dailyRewardAmounts={coins:DAILY_FREE_COINS,tickets:200};
export const rewardAmounts={coins:REWARDED_AD_COINS,tickets:200}; // Tickets stored in tenths: 200 = 20 tickets.
export const AD_LIMIT=3, AD_DAILY_LIMIT=12, AD_COOLDOWN=20*60*1000;
export const newRewards=():RewardState=>({lastSeen:0,daily:{coins:'',tickets:''},ads:{coins:{remaining:3,readyAt:0},tickets:{remaining:3,readyAt:0}},adDays:{coins:{day:'',used:0},tickets:{day:'',used:0}}});
export const dayKey=(now:number)=>new Date(now+9*60*60*1000).toISOString().slice(0,10); // Asia/Seoul
export function normalizeRewards(value:unknown):RewardState {
 const out=newRewards(),v=value as Partial<RewardState>|null;
 if(!v||typeof v!=='object')return out;
 if(Number.isSafeInteger(v.lastSeen)&&v.lastSeen!>=0)out.lastSeen=v.lastSeen!;
 for(const currency of ['coins','tickets'] as const){
  const day=v.daily?.[currency];if(typeof day==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(day))out.daily[currency]=day;
  const q=v.ads?.[currency];if(q&&Number.isInteger(q.remaining)&&q.remaining>=0&&q.remaining<=3&&Number.isSafeInteger(q.readyAt)&&q.readyAt>=0&&(q.remaining!==0||q.readyAt>0))out.ads[currency]={...q};
  const d=v.adDays?.[currency];if(d&&/^\d{4}-\d{2}-\d{2}$/.test(d.day)&&Number.isInteger(d.used)&&d.used>=0&&d.used<=AD_DAILY_LIMIT)out.adDays[currency]={...d};
 }
 return out;
}
export function rewardStatus(state:RewardState,currency:RewardCurrency,now=Date.now()){
 const time=Math.max(now,state.lastSeen),quota=state.ads[currency],recharged=quota.remaining===0&&time>=quota.readyAt;
 const day=dayKey(time),used=state.adDays[currency].day===day?state.adDays[currency].used:0;
 const dailyLeft=AD_DAILY_LIMIT-used,remaining=Math.min(dailyLeft,recharged?AD_LIMIT:quota.remaining);
 const batchWait=recharged||quota.remaining>0?0:Math.max(0,quota.readyAt-time);
 const dayWait=dailyLeft>0?0:Date.parse(day+'T00:00:00+09:00')+86400000-time;
 return {dailyAvailable:state.daily[currency]!==day,remaining,waitMs:Math.max(batchWait,dayWait),dailyRemaining:dailyLeft};
}
/** Mutates only after a completed reward event; caller persists wallet and policy together. */
export function consumeReward(state:RewardState,currency:RewardCurrency,kind:'daily'|'ad',now=Date.now()):boolean{
 const time=Math.max(now,state.lastSeen),status=rewardStatus(state,currency,time);
 if(kind==='daily'){if(!status.dailyAvailable)return false;state.daily[currency]=dayKey(time);}
 else {if(status.remaining<=0)return false;const remaining=status.remaining-1;state.ads[currency]={remaining,readyAt:remaining===0?time+AD_COOLDOWN:0};state.adDays[currency]={day:dayKey(time),used:AD_DAILY_LIMIT-status.dailyRemaining+1};}
 state.lastSeen=time;return true;
}
