import {ExpansionSlot,ExpansionFrame,expansionCells as cells,randomIndex} from './ExpansionCore';
import {SpinResult,Win} from './SlotMain';
import {STONE_MODEL,stoneNewPrize,stoneOrdinaryInput,stoneUniform} from './StoneMath';
/** Official Coin Grab family; royal promotion timing and prize odds are local rules. */
export class StoneKingSlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){super(spec);for(const name of ['crown','portrait','hand'])this.config.symbols.push({id:this.id(name),name,color:'#70cc91',weight:0,payout:0});this.config.description='5×3 · 25라인 · 왼쪽부터 연결\n석상 BONUS 3개 이상: 해당 위치를 상금 코인으로 바꾸고 리스핀 3회에 진입합니다.\n새 코인 착지 후 3회로 복구합니다. 석조 왕은 이번에 새로 나온 코인 하나를 왕관 코인으로 승급해 금액을 2배로 만듭니다.\n빈칸만 회전하며 종료 시 고정 상금을 한 번씩 수집합니다. 15칸 완성은 별도 25배 상금입니다.\n왕의 승급·확률·금액은 로컬 각색 규칙이며 공유 잭팟 적립은 없습니다.';}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-stone';}
 unit(symbol:number,count:number){return (.025+.015*(8-symbol))*Math.pow(2,Math.max(0,count-3));}
 private plainBoard(bet:number,rng:()=>number){if(!this.bets.includes(bet))throw Error('Invalid bet');return Array.from({length:15},()=>this.id(stoneOrdinaryInput(bet,rng)));}
 draw(bet:number,rng:()=>number){const board=this.plainBoard(bet,rng);for(let col=0;col<5;col++)if(stoneUniform(rng)<STONE_MODEL.scatterPerReel)board[randomIndex(rng,3)*5+col]=this.id('scatter');return board;}
 private hold(board:string[],bet:number,rng:()=>number,base:SpinResult){
  const values=new Map<number,number>(cells(board,this.id('scatter')).map(c=>[c,[1,2,3,5][randomIndex(rng,4)]])),royal=new Set<number>(),rounds=[base],snapshots:{frame:ExpansionFrame;values:Map<number,number>}[]=[];let left=3;
  const frame=(action:ExpansionFrame['action'],caption:string,focus:number[]=[],previous=Array.from(values.keys()))=>{const b=Array.from({length:15},(_,c)=>values.has(c)?this.id(royal.has(c)?'crown':'coin'):''),f=this.frame(b,action,caption,focus,{held:previous,remaining:left,panel:{label:'KING VAULT',values:[values.size,royal.size],columns:2}});snapshots.push({frame:f,values:new Map(values)});return f;};
  rounds.push(this.round(bet,[frame('reveal','석상 표식 → 고정 상금 · 리스핀 3회')]));
  while(left>0&&values.size<15){left--;const previous=Array.from(values.keys()),fs:ExpansionFrame[]=[],landed:number[]=[];
   for(let c=0;c<15;c++)if(!values.has(c)&&stoneUniform(rng)<STONE_MODEL.landing){values.set(c,stoneNewPrize(rng));landed.push(c);}
   fs.push(frame('reels','석조 왕 금고 · 빈칸 회전',[],previous));
   if(landed.length){left=3;fs.push(frame('reveal','새 상금 착지 · 리스핀 3회 복구',landed,previous));const target=landed[randomIndex(rng,landed.length)];fs.push(frame('trigger','석조 왕의 손 → 새 코인 승급',[target]));values.set(target,values.get(target)!*2);royal.add(target);fs.push(frame('effect','왕관 코인 · 표시 상금 2배',[target]));}
   fs.push(frame('state','남은 리스핀 '+left+'회'));rounds.push(this.round(bet,fs));
  }
  left=0;const paid=frame('collect','석조 왕 금고 → 상금 한 번씩 수집',Array.from(values.keys()));paid.wins=Array.from(values).map(([cell,value]):Win=>({line:-1,symbol:this.id(royal.has(cell)?'crown':'coin'),cells:[cell],amount:bet*value,multiplier:value}));
  const awards=new Map(paid.wins.map(w=>[w.cells[0],w]));for(const snapshot of snapshots)snapshot.frame.coinAwards=Array.from(snapshot.values).map(([cell,value])=>({cell,win:awards.get(cell)!,fraction:value/values.get(cell)!}));
  const fs=[paid];if(values.size===15)fs.push(this.frame(paid.board,'win','15칸 완성 · 왕실 상금',Array.from(values.keys()),{wins:[{line:-1,symbol:this.id('wild'),cells:Array.from(values.keys()),amount:bet*25,multiplier:25}]}));rounds.push(this.round(bet,fs));return this.finish(rounds,{featureOnly:true});
 }
 play(board:string[],bet:number,rng:()=>number){this.validate(board,bet);const base=this.ordinary(board,bet),found=cells(board,this.id('scatter'));if(found.length<3)return this.finish([base]);base.expansionFeature!.frames.push(this.frame(board,'trigger','석상 BONUS '+found.length+'개 · 왕실 금고',found));return this.hold(board,bet,rng,base);}
 prepareBonusPurchase(bet:number,rng:()=>number){
  const board=this.plainBoard(bet,rng),reels=[0,1,2,3,4],found:number[]=[];
  for(let i=0;i<3;i++){const j=i+randomIndex(rng,5-i);[reels[i],reels[j]]=[reels[j],reels[i]];const cell=randomIndex(rng,3)*5+reels[i];board[cell]=this.id('scatter');found.push(cell);}
  return this.purchaseFromResult(this.hold(board,bet,rng,this.round(bet,[this.frame(board,'trigger','독립 왕실 금고 구매',found)])));
 }
}
