/** Book of Tut base edition: official game page + Player rules p140.
 * Selection randomness and natural reels belong to the engine, not this lifecycle. */
export interface TutBonusState {
 selected:number; remaining:number; played:number;
 phase:'ready'|'spinning'|'complete';
}
function count(n:number,min:number,max:number,label:string){
 if(!Number.isSafeInteger(n)||n<min||n>max)throw Error('Invalid Tut '+label);
}
function validate(s:TutBonusState){
 count(s.selected,0,8,'selected symbol');count(s.remaining,0,Number.MAX_SAFE_INTEGER,'remaining');count(s.played,0,Number.MAX_SAFE_INTEGER,'played');
 if(!['ready','spinning','complete'].includes(s.phase))throw Error('Invalid Tut phase');
 if(s.phase==='ready'&&!s.remaining)throw Error('Tut ready without spins');
 if(s.phase==='complete'&&s.remaining)throw Error('Tut complete with spins');
}
export function tutStartBonus(books:number,selected:number):TutBonusState{
 count(books,3,15,'trigger books');count(selected,0,8,'selected symbol');
 return {selected,remaining:10,played:0,phase:'ready'};
}
export function tutBeginBonusSpin(state:TutBonusState):TutBonusState{
 validate(state);if(state.phase!=='ready')throw Error('Tut bonus spin is not ready');
 count(state.played+1,1,Number.MAX_SAFE_INTEGER,'played');
 return {...state,remaining:state.remaining-1,played:state.played+1,phase:'spinning'};
}
/** Commit after the result's book hit is shown. Render +addedSpins at this
 * transition; do not display the future remaining count at spin generation. */
export function tutFinishBonusSpin(state:TutBonusState,books:number){
 validate(state);if(state.phase!=='spinning')throw Error('Tut bonus spin is not running');
 count(books,0,15,'result books');
 const addedSpins=books>=3?10:0,remaining=state.remaining+addedSpins;
 count(remaining,0,Number.MAX_SAFE_INTEGER,'remaining');
 const after:TutBonusState={...state,remaining,phase:remaining?'ready':'complete'};
 return {before:{...state},addedSpins,after};
}
