import {SpinResult,SlotMain} from './SlotMain';
/** Awards and displayed paytables use the engine's stated rules without economy scaling. */
export function payoutScale(_slot:SlotMain,_bet?:number){return 1;}
/** Preserve evaluated boards, bonus sequences and hit classification; settle integer coins once. */
export function scalePayout(result:SpinResult,scale:number,rng:()=>number,maximum=Number.MAX_SAFE_INTEGER):SpinResult {
 if(!result.payout)return result;
 const rounds=result.rounds||[result],base=rounds[0],baseWins=new Set(base.wins.filter(w=>w.amount>0));
 const wins=Array.from(new Set(rounds.flatMap(r=>r.wins))),weights=wins.map(w=>w.amount),sum=weights.reduce((a,b)=>a+b,0);
 if(sum<=0)throw Error('Positive payout without winning entries');
 const expected=Math.max(1,Math.min(maximum,result.payout*scale)),budget=Math.floor(expected)+(rng()<expected%1?1:0);
 const shares=weights.map(amount=>budget*amount/sum),amounts=shares.map(Math.floor);
 let left=budget-amounts.reduce((a,b)=>a+b,0);
 const order=shares.map((share,i)=>({i,fraction:share-amounts[i]})).sort((a,b)=>b.fraction-a.fraction||a.i-b.i);
 for(let i=0;i<left;i++)amounts[order[i].i]++;
 // A base hit remains a real positive award even when a large bonus dominates its share.
 if(baseWins.size&&!wins.some((w,i)=>baseWins.has(w)&&amounts[i]>0)){
  const recipient=wins.findIndex(w=>baseWins.has(w)),donor=amounts.indexOf(Math.max(...amounts));amounts[donor]--;amounts[recipient]++;
 }
 wins.forEach((w,i)=>w.amount=amounts[i]);
 for(const round of rounds){round.payout=round.wins.reduce((n,w)=>n+w.amount,0);round.cascades?.forEach(stage=>stage.payout=stage.wins.reduce((n,w)=>n+w.amount,0));round.legacyFeature?.expansions.forEach(phase=>phase.payout=phase.wins.reduce((sum,win)=>sum+win.amount,0));round.moonFeature?.stages.forEach(stage=>stage.payout=stage.wins.reduce((n,w)=>n+w.amount,0));round.tomeFeature?.stages.forEach(stage=>{stage.awards=stage.wins.map(win=>win.amount);stage.payout=stage.awards.reduce((sum,n)=>sum+n,0);});if(round.multiplierCollection)round.multiplierCollection.subtotal=(round.cascades||[]).reduce((n,stage)=>n+stage.payout,0);}
 for(const round of rounds)round.rhinoFeature?.stages.forEach(stage=>stage.payout=stage.wins.reduce((sum,win)=>sum+win.amount,0));
 if(result.rounds)result.payout=rounds.reduce((n,r)=>n+r.payout,0);
 // A selected Moon branch shares its wins/rounds with the outer result, but
 // its numeric aggregate is a separate property. Keep that view consistent.
 result.moonChoices?.forEach(choice=>choice.payout=choice.wins.reduce((sum,win)=>sum+win.amount,0));
 if(result.payout!==budget)throw Error('Payout allocation mismatch');
 return result;
}
